"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000 or amount.as_tuple().exponent < -2:
            return None
        return int(amount.to_integral_value(rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    raise NotImplementedError


def load_records(text):
    records = []
    seen_record_ids = set()
    for line in text.strip().splitlines():
        fields = line.split('|')
        if len(fields) != 6:
            continue
        record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
        record_type = record_type.upper()
        if currency != 'USD' or record_type not in {'ORDER', 'PAYMENT'}:
            continue
        record_id = record_id.strip()
        order_id = order_id.strip()
        if not record_id or not order_id or not order_id.startswith('ORD-'):
            continue
        try:
            amount = Decimal(amount)
            if amount < 0 or amount > 1000000:
                continue
            amount = int(amount * 100)  # Convert to cents
        except (InvalidOperation, ValueError):
            continue
        if record_id in seen_record_ids:
            continue
        seen_record_ids.add(record_id)
        records.append({
            'type': record_type,
            'record_id': record_id,
            'order_id': order_id,
            'amount': amount,
            'currency': currency,
            'timestamp': datetime.fromisoformat(timestamp)
        })
    return records


def match_payments(records):
    orders = {}
    payments = []
    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    matches = []
    for payment in payments:
        order_id = payment['order_id']
        if order_id in orders:
            order_time = orders[order_id]['timestamp']
            payment_time = payment['timestamp']
            if payment_time < order_time + timedelta(hours=72):
                matches.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': payment['amount']
                })
            else:
                matches.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })
    return matches


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += -record['amount']  # Add the positive equivalent of the negative amount
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

