"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount_decimal = Decimal(s)
        if amount_decimal > 1000000 or amount_decimal < -1000000:
            return None
        amount_cents = int(amount_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip():
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount_decimal = Decimal(amount)
        if amount_decimal > 1000000 or amount_decimal < -1000000:
            return None
        amount_cents = int(amount_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp_dt
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders[record['ORDER_ID']] = record['TIMESTAMP']
        elif record['TYPE'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order_timestamp in orders.items():
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order_id:
                if payment['TIMESTAMP'] < order_timestamp + timedelta(hours=72):
                    if matched_payment is None or payment['TIMESTAMP'] < matched_payment['TIMESTAMP']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -matched_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refunds = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in order_ids:
            total_refunds += -record['AMOUNT']

    return total_refunds


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')

    net_total = sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

