"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    s = s.strip()
    if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    if s.count('-') > 1 or (s.count('-') == 1 and s[0] != '-'):
        return None
    if s.count('.') == 1:
        integer_part, fractional_part = s.split('.')
        if len(fractional_part) > 3:
            return None
        if len(fractional_part) == 3:
            s = f"{integer_part}.{fractional_part[:2]}"
        else:
            s = f"{integer_part}.{fractional_part}"
    try:
        amount = Decimal(s)
    except InvalidOperation:
        return None
    if abs(amount) > 1000000:
        return None
    return int(amount.to_integral_value(rounding=ROUND_HALF_UP) * 100)


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_str, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount_str.strip())
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in {'ORDER', 'PAYMENT'}:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id:
        return None
    if currency != 'USD':
        return None
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None
    if not (len(timestamp) == 16 or len(timestamp) == 19) or not (timestamp[:10].count('-') == 2 and timestamp[10] == ' '):
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER' and record['currency'] == 'USD']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['currency'] == 'USD' and record['amount'] >= 0]

    results = []
    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M')
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and
            order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M') < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: (p['timestamp'], p['record_id']))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches) - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

