"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for scientific notation
        if 'e' in s or 'E' in s:
            return None

        # Check for valid fractional digits
        if amount.as_tuple().exponent < -3:
            return None

        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to cents
        cents = int(amount * 100)

        # Check for absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = parts

    # Validate TYPE
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None

    # Validate ORDER_ID
    if not order_id.startswith('ORD-'):
        return None

    # Validate AMOUNT and CURRENCY
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate TIMESTAMP
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            order_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            orders[record['order_id']] = {
                'timestamp': order_time,
                'amount': record['amount']
            }
        elif record['type'] == 'PAYMENT':
            payment_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            payments.append((record['order_id'], record['amount'], payment_time))

    results = []

    for order_id, order_info in orders.items():
        order_timestamp = order_info['timestamp']
        matched_amount = 0
        matched = False

        for payment_order_id, payment_amount, payment_timestamp in payments:
            if payment_order_id == order_id and order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                matched_amount += abs(payment_amount)
                matched = True
                break

        results.append({
            'order_id': order_id,
            'status': 'matched' if matched else 'unmatched',
            'amount': matched_amount if matched else 0
        })

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            total_refund += abs(record['amount'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

