"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    s = s.strip()
    if 'e' in s or 'E' in s:
        return None
    if s.count('.') > 1:
        return None
    if s.startswith('-'):
        s = s[1:]
    if not s.replace('.', '').isdigit():
        return None
    if '.' in s:
        whole, frac = s.split('.')
        if len(frac) > 3:
            return None
        amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    else:
        amount = Decimal(s)

    amount_cents = int(amount * 100)
    if abs(amount_cents) > 1000000:
        return None
    return amount_cents


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id or not order_id.startswith('ORD-'):
        return None
    try:
        amount = round(Decimal(amount), 2)
        if abs(amount) > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None
    if currency != 'USD':
        return None
    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    matches = []

    for order in orders:
        order_id = order['order_id']
        order_time = order['timestamp']
        matched_payment = None

        for payment in payments:
            payment_time = payment['timestamp']
            if (payment['order_id'] == order_id and 
                payment_time > order_time and 
                payment_time < order_time + timedelta(hours=72)):
                if matched_payment is None or payment_time < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    refund_total = Decimal('0.00')
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += abs(record['amount'])

    return float(refund_total)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': float(refund_total),
        'net_total': float(net_total),
        'unmatched_ids': unmatched_ids
    }

