"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid numeric string
        if not isinstance(s, str) or s.count('.') > 1 or 'e' in s or 'E' in s:
            return None

        # Convert to Decimal and round
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None

        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3]
    currency = fields[4]
    timestamp = fields[5]

    if not record_id or not order_id:
        return None

    if not order_id.startswith('ORD-'):
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    if currency != 'USD':
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': parsed_amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    seen_ids = set()
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            seen_ids.add(record['RECORD_ID'])
            valid_records.append(record)

    return valid_records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders.append(record)
        elif record['TYPE'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        order_time = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        matched_payment = None

        for payment in payments:
            payment_time = datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
            if payment['ORDER_ID'] == order['ORDER_ID'] and payment_time < order_time and (order_time - payment_time) < timedelta(hours=72):
                if matched_payment is None or payment_time < matched_payment['TIMESTAMP']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order['ORDER_ID'],
                'status': 'matched',
                'amount': abs(matched_payment['AMOUNT'])
            })
        else:
            results.append({
                'order_id': order['ORDER_ID'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refunds = 0
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in valid_orders:
            total_refunds += abs(record['AMOUNT'])

    return total_refunds


def build_summary(matches, refund_total):
    total_orders = len(set(match['order_id'] for match in matches))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

