"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 6:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount_str = parts[3].strip()
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if not (record_type in ['ORDER', 'PAYMENT']):
        return None
    if not order_id.startswith('ORD-'):
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []
    matched_orders = set()

    for order_id, order in orders.items():
        order_time = order['timestamp']
        matched_payment = None

        for payment in payments:
            if payment['order_id'] == order_id and payment['amount'] >= 0:
                payment_time = payment['timestamp']
                if payment_time < order_time + timedelta(hours=72):
                    if matched_payment is None or payment_time < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
            matched_orders.add(order_id)
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    # Deduplicate unmatched orders
    unique_results = {result['order_id']: result for result in results if result['order_id'] not in matched_orders}
    results = [result for result in results if result['order_id'] in matched_orders] + list(unique_results.values())

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['order_id'] in order_ids:
            refund_total += -record['amount']  # Add the positive value of the negative amount

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(set(match['order_id'] for match in matches))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

