"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for invalid formats (scientific notation, etc.)
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal for precise rounding
        amount = Decimal(s)

        # Check for absolute value exceeding 1,000,000 cents
        if abs(amount) > 1000000:
            return None

        # Round to two decimal places (cents)
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, parts)

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        amount = parse_amount(amount_str)
        if amount is None:
            return None

        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except (ValueError, TypeError):
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders[record['ORDER_ID']] = record

    for record in records:
        if record['TYPE'] == 'PAYMENT':
            order_id = record['ORDER_ID']
            if order_id in orders:
                order_timestamp = orders[order_id]['TIMESTAMP']
                payment_timestamp = record['TIMESTAMP']

                if payment_timestamp < order_timestamp + timedelta(hours=72) and record['AMOUNT'] >= 0:
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['AMOUNT']
                    })
                    # Remove the order to prevent further matches
                    del orders[order_id]
                else:
                    results.append({
                        'order_id': order_id,
                        'status': 'unmatched',
                        'amount': 0
                    })

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_order_ids:
            total_refund += abs(record['AMOUNT'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

