"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if 'e' in s or 'E' in s:
            return None
        d = Decimal(s)
        if abs(d) > 1000000:
            return None
        return int(d.to_integral_value(rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        parsed_amount = parse_amount(amount)
        if parsed_amount is None:
            return None
    except Exception:
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': parsed_amount,
        'CURRENCY': currency,
        'TIMESTAMP': parsed_timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = {}
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record is not None:
            record_id = record['RECORD_ID']
            if record_id not in records:
                records[record_id] = record
                valid_records.append(record)

    return valid_records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders[record['ORDER_ID']] = record
        elif record['TYPE'] == 'PAYMENT':
            payments.append(record)

    results = []
    for order_id, order in orders.items():
        order_time = order['TIMESTAMP']
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order_id and payment['AMOUNT'] >= 0:
                if order_time < payment['TIMESTAMP'] < order_time + timedelta(hours=72):
                    if matched_payment is None or payment['TIMESTAMP'] < matched_payment['TIMESTAMP']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in order_ids:
            total_refund += -record['AMOUNT']

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches) + len([m for m in matches if m['status'] == 'unmatched'])
    matched_count = sum(1 for m in matches if m['status'] == 'matched')
    net_total = sum(m['amount'] for m in matches if m['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(m['order_id'] for m in matches if m['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

