"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s) or s.count('-') > 1:
            return None
        if s.count('-') == 1 and s[0] != '-':
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for valid digits
        if amount.as_tuple().exponent < -2 or amount == 0:
            return None

        # Round using round-half-up
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        cents = int(amount * 100)

        # Check absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = fields

    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    if currency != 'USD':
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    if record_type == 'PAYMENT' and amount >= 0:
        amount = -amount

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            order_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S') if ':' in record['timestamp'] else datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M')
            orders[record['order_id']] = (order_time, record['amount'])
        elif record['type'] == 'PAYMENT' and record['amount'] < 0:
            continue  # Skip refunds

        if record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, (order_time, order_amount) in orders.items():
        matched_payment = None

        for payment in payments:
            payment_time = datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') if ':' in payment['timestamp'] else datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M')
            if payment['order_id'] == order_id and order_time <= payment_time < order_time + timedelta(hours=72):
                if matched_payment is None or payment_time < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            results.append({'order_id': order_id, 'status': 'matched', 'amount': -matched_payment['amount']})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    refund_total = 0

    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
