"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        amount_cents = int(amount * 100 + (0.5 if amount_str[-1] == '5' else 0))
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = fields[1].strip()
    if not record_id:
        return None

    order_id = fields[2].strip()
    if not order_id.startswith('ORD-'):
        return None

    amount_str = fields[3].strip()
    try:
        amount = Decimal(amount_str)
        if amount < 0:
            amount = -amount
        amount_cents = int(amount * 100 + (0.5 if amount_str[-1] == '5' else 0))
        if abs(amount_cents) > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None

    currency = fields[4].strip()
    if currency != 'USD':
        return None

    timestamp_str = fields[5].strip()
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            seen_ids.add(record['RECORD_ID'])
            records.append(record)
    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = sorted([record for record in records if record['TYPE'] == 'PAYMENT'], key=lambda x: x['TIMESTAMP'])

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = order['TIMESTAMP']
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order_id and payment['TIMESTAMP'] > order_timestamp and payment['TIMESTAMP'] <= order_timestamp + timedelta(hours=72):
                matched_payment = payment
                break

        if matched_payment:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -matched_payment['AMOUNT']
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}
    total_refund = sum(-record['AMOUNT'] for record in records if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_order_ids)
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(-match['amount'] for match in matches) - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

