"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if s.count('.') > 1 or any(c not in '-0123456789.' for c in s):
            return None

        # Convert to Decimal and round
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None

        # Convert to cents and round
        cents = int(amount * 100 + Decimal('0.005').quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    amount = parse_amount(amount)
    if amount is None and record_type == 'PAYMENT':
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp.strftime('%Y-%m-%d %H:%M:%S') if ':' in timestamp else timestamp.strftime('%Y-%m-%d %H:%M')
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            seen_record_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    matches = []
    orders = {record['order_id']: record['timestamp'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order_timestamp = orders[order_id]
                payment_timestamp = record['timestamp']
                if payment_timestamp >= order_timestamp and payment_timestamp < order_timestamp + timedelta(hours=72):
                    matches.append({'order_id': order_id, 'status': 'matched', 'amount': record['amount']})
                    break
    else:
        for order_id in orders:
            matches.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return matches


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids)
    return abs(refund_total) if refund_total < 0 else 0


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches) - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

