"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check if the amount is a valid numeric string
        if not isinstance(s, str) or s.count('.') > 1 or 'e' in s.lower():
            return None

        # Convert to Decimal and round to cents
        amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        amount_cents = int(amount * 100)

        # Ensure absolute value does not exceed 1,000,000 cents
        if abs(amount_cents) > 1000000:
            return None

        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3].strip()
    currency = fields[4].strip()
    timestamp = fields[5].strip()

    if not record_id or not order_id:
        return None

    if not order_id.startswith('ORD-'):
        return None

    amount_value = parse_amount(amount)
    if amount_value is None:
        return None

    if currency != 'USD':
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount_value,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = []
    seen_record_ids = set()

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_record_ids:
            valid_records.append(record)
            seen_record_ids.add(record['RECORD_ID'])

    return valid_records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders.append(record)
        elif record['TYPE'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order_id:
                payment_timestamp = datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
                if payment_timestamp < order_timestamp and (order_timestamp - payment_timestamp) < timedelta(hours=72):
                    if matched_payment is None or payment_timestamp < matched_payment['TIMESTAMP']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': abs(matched_payment['AMOUNT'])
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refunds = 0
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0:
            if record['ORDER_ID'] in valid_orders:
                total_refunds += abs(record['AMOUNT'])

    return total_refunds


def build_summary(matches, refund_total):
    total_orders = len(set(match['order_id'] for match in matches))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

