"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 6:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parts[3].strip()
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if not amount.replace('.', '', 1).isdigit() or amount.count('.') > 1:
        return None
    if currency != 'USD':
        return None

    try:
        dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    if (record_type == 'ORDER' and Decimal(amount) < 0) or (record_type == 'PAYMENT' and Decimal(amount) >= 0):
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': dt
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders[record['ORDER_ID']] = {
                'status': 'unmatched',
                'amount': 0,
                'timestamp': record['TIMESTAMP']
            }
        elif record['TYPE'] == 'PAYMENT':
            payments.append(record)

    for order_id, order in orders.items():
        order_timestamp = order['timestamp']
        cutoff_time = order_timestamp + timedelta(hours=72)

        matching_payments = [
            payment for payment in payments 
            if payment['ORDER_ID'] == order_id and order_timestamp <= payment['TIMESTAMP'] < cutoff_time
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: p['TIMESTAMP'])
            order['status'] = 'matched'
            order['amount'] = parse_amount(earliest_payment['AMOUNT'])

    return [{'order_id': order_id, 'status': order['status'], 'amount': order['amount']} for order_id, order in orders.items()]


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_order_ids:
            amount = parse_amount(record['AMOUNT'])
            if amount is not None and amount < 0:
                refund_total += -amount  # Add positive value of the refund

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

