"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check if the format is valid
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal for rounding
        amount = Decimal(s)

        # Apply round-half-up for third fractional digits
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to cents
        amount_cents = int(amount * 100)

        # Check constraints
        if amount_cents < 0 or abs(amount_cents) > 1000000:
            return None

        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    if not order_id.startswith('ORD-') or len(order_id) <= 4:
        return None

    try:
        amount = int(amount_str)
        if amount < 0 or amount > 1000000:
            return None
    except ValueError:
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])
    return records


def match_payments(records):
    matches = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for order_id, order in orders.items():
        matched_amount = 0
        matched = False

        for record in records:
            if record['type'] == 'PAYMENT' and record['order_id'] == order_id and record['amount'] >= 0:
                if order['timestamp'] <= record['timestamp'] < order['timestamp'] + timedelta(hours=72):
                    matched_amount += record['amount']
                    matched = True

        matches.append({
            'order_id': order_id,
            'status': 'matched' if matched else 'unmatched',
            'amount': matched_amount if matched else 0
        })

    return matches


def compute_refunds(records):
    refund_total = 0
    valid_orders = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_orders:
            refund_total += -record['amount']  # Convert to positive

    return refund_total


def build_summary(matches, refund_total):
    total_orders = sum(1 for match in matches if match['status'] == 'matched' or match['status'] == 'unmatched')
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

