"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        d = Decimal(s)
        if d != d.to_integral_value():
            d = d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        cents = int(d * 100)
        if abs(cents) > 1000000 or d.as_tuple().exponent < -2 or d.as_tuple().exponent > 0:
            return None
        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-') or not record_id or not amount or not currency or not timestamp:
        return None
    if currency != 'USD':
        return None
    amount_cents = parse_amount(amount)
    if amount_cents is None or (record_type.upper() == 'ORDER' and amount_cents < 0):
        return None
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None
    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and payment['amount'] >= 0
            and order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            selected_payment = min(matching_payments, key=lambda p: (datetime.strptime(p['timestamp'], '%Y-%m-%d %H:%M:%S'), payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': selected_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

