"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not all(field.strip() for field in [record_id, order_id]):
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        amount = Decimal(amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None
    if amount.as_tuple().exponent < -3:
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': str(amount),
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = []
    seen_ids = set()

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    for record in records:
        if record['TYPE'] == 'ORDER':
            order_id = record['ORDER_ID']
            order_timestamp = datetime.strptime(record['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
            matching_payments = [
                payment for payment in records
                if payment['TYPE'] == 'PAYMENT' and
                payment['ORDER_ID'] == order_id and
                datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S') < order_timestamp + timedelta(hours=72)
            ]
            if matching_payments:
                earliest_payment = min(matching_payments, key=lambda p: (datetime.strptime(p['TIMESTAMP'], '%Y-%m-%d %H:%M:%S'), records.index(p)))
                matches.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': int(abs(Decimal(earliest_payment['AMOUNT'])) * 100)
                })
            else:
                matches.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })
    return matches


def compute_refunds(records):
    refund_total = Decimal('0.00')
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and Decimal(record['AMOUNT']) < 0:
            order_id = record['ORDER_ID']
            if order_id in valid_order_ids:
                refund_total += abs(Decimal(record['AMOUNT']))

    return int(refund_total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

