"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for scientific notation
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal and round
        amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        cents = int(amount * 100)

        # Check for valid range
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = fields

    # Validate TYPE
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate ORDER_ID
    if not order_id.startswith('ORD-'):
        return None

    # Validate AMOUNT
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate CURRENCY
    if currency != 'USD':
        return None

    # Validate TIMESTAMP
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order_timestamp = datetime.strptime(orders[order_id]['timestamp'], '%Y-%m-%d %H:%M:%S')
                payment_timestamp = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')

                if 0 <= (payment_timestamp - order_timestamp).total_seconds() < 72 * 3600:
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue

    for order_id in orders:
        if order_id not in [result['order_id'] for result in results]:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            total_refund += -record['amount']  # Add positive value of refund

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

