"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        # Replace commas and check for valid format
        s = s.replace(',', '')
        if s.count('.') > 1 or len(s.split('.')[-1]) > 3:
            return None
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        # Round to nearest cent using round-half-up
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_str, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id[4:]:
        return None
    if currency != 'USD':
        return None

    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record not in records:
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []
    for order_id, order in orders.items():
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
        matched_payment = None

        for payment in payments:
            if payment['order_id'] == order_id and payment['amount'] >= 0:
                payment_timestamp = datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S')
                if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                    if matched_payment is None or payment_timestamp < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['order_id'] in order_ids and record['amount'] < 0:
            refund_total += -record['amount']
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

