"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if not (record_type in ['ORDER', 'PAYMENT'] and order_id.startswith('ORD-') and amount is not None and currency == 'USD'):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = {}
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in records:
            records[record['record_id']] = record
            valid_records.append(record)

    return valid_records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    matches = []
    matched_orders = set()

    for order in orders:
        order_time = order['timestamp']
        earliest_payment = None

        for payment in payments:
            if payment['order_id'] == order['order_id'] and payment['timestamp'] < order_time + timedelta(hours=72):
                if earliest_payment is None or payment['timestamp'] < earliest_payment['timestamp']:
                    earliest_payment = payment

        if earliest_payment:
            matches.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
            matched_orders.add(order['order_id'])
        else:
            matches.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    # Deduplicate unmatched orders
    unmatched_orders = {match['order_id']: match for match in matches if match['status'] == 'unmatched'}
    return list(unmatched_orders.values()) + [match for match in matches if match['status'] == 'matched']


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['order_id'] in order_ids:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(set(match['order_id'] for match in matches))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

