"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s) or 'e' in s.lower():
            return None
        if s.count('-') > 1 or (s.count('-') == 1 and s[0] != '-'):
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for valid range
        if abs(amount) > 1000000:
            return None

        # Round to nearest cent
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id:
        return None
    if currency != 'USD':
        return None
    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None
    if record_type == 'ORDER' and parsed_amount < 0:
        return None
    if record_type == 'PAYMENT' and parsed_amount >= 0:
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': parsed_timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        qualifying_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and
            order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    valid_orders = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_orders)
    return refund_total if refund_total > 0 else 0


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(-match['amount'] for match in matches) - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

