"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
    if not record_id or not order_id or currency != 'USD':
        return None
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    amount = parse_amount(amount)
    if amount is None:
        return None
    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record:
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S') if ':' in order['timestamp'] else datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M')
        end_time = order_timestamp + timedelta(hours=72)

        qualifying_payments = [payment for payment in payments if payment['order_id'] == order_id and order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') < end_time]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: (datetime.strptime(p['timestamp'], '%Y-%m-%d %H:%M:%S'), payments.index(p)))
            results.append({'order_id': order_id, 'status': 'matched', 'amount': earliest_payment['amount']})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    return sum(-payment['amount'] for payment in records if payment['type'] == 'PAYMENT' and payment['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['record_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

