"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if not isinstance(s, str) or len(s) == 0:
            return None

        # Convert to Decimal for accurate rounding
        amount = Decimal(s)

        # Check for scientific notation or invalid format
        if amount != amount.to_integral_value():
            return None

        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        cents = int(amount * 100)

        # Check absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = fields

    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id or not currency or not timestamp:
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None
    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
        end_time = order_timestamp + timedelta(hours=72)

        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') < end_time
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: (datetime.strptime(p['timestamp'], '%Y-%m-%d %H:%M:%S'), payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

