"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid format and reject scientific notation
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal for precision
        amount = Decimal(s)

        # Check for absolute value exceeding 1,000,000 cents
        if abs(amount) > 1000000:
            return None

        # Round to two decimal places and convert to integer cents
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = [field.strip() for field in fields]

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if currency != 'USD':
        return None
    if not order_id.startswith('ORD-'):
        return None
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    if parse_amount(amount) is None:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        matching_payments = [
            payment for payment in payments
            if payment['ORDER_ID'] == order_id and
            order_timestamp <= datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S') < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: datetime.strptime(p['TIMESTAMP'], '%Y-%m-%d %H:%M:%S'))
            amount = parse_amount(earliest_payment['AMOUNT'])
            results.append({'order_id': order_id, 'status': 'matched', 'amount': amount})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_order_ids:
            amount = parse_amount(record['AMOUNT'])
            if amount is not None and amount < 0:
                total_refund += -amount  # Add positive value of refund

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

