"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for valid range
        if abs(amount) > 1000000:
            return None

        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to cents as integer
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = parts

    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    if not order_id.startswith('ORD-'):
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp.strftime('%Y-%m-%d %H:%M:%S') if ':' in timestamp.strftime('%Y-%m-%d %H:%M') else timestamp.strftime('%Y-%m-%d %H:%M')
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    matched_orders = []
    order_dict = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for order_id, order in order_dict.items():
        order_time = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
        match_found = False
        best_payment = None

        for record in records:
            if record['type'] == 'PAYMENT' and record['order_id'] == order_id:
                payment_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
                if order_time <= payment_time < order_time + timedelta(hours=72):
                    if not match_found or payment_time < best_payment['timestamp']:
                        best_payment = record
                        match_found = True

        if match_found:
            matched_orders.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': best_payment['amount']
            })
        else:
            matched_orders.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matched_orders


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            total_refund += -record['amount']

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

