"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal for accurate rounding
        amount = Decimal(s)

        # Round to nearest cent
        amount = amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)

        # Convert to cents
        cents = int(amount * 100)

        # Check for absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = fields

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    record_type = record_type.upper()

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp.strftime('%Y-%m-%d %H:%M:%S') if ':' in timestamp.strftime('%Y-%m-%d %H:%M') else timestamp.strftime('%Y-%m-%d %H:%M')
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    results = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for order in orders.values():
        matched = False
        order_timestamp = order['timestamp']
        order_id = order['order_id']
        earliest_payment = None

        for record in records:
            if record['type'] == 'PAYMENT' and record['order_id'] == order_id:
                payment_timestamp = record['timestamp']
                if order_timestamp <= payment_timestamp < order_timestamp + timedelta(hours=72):
                    if earliest_payment is None or payment_timestamp < earliest_payment['timestamp']:
                        earliest_payment = record

        if earliest_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids)
    return max(refund_total, 0)  # Ensure non-negative total


def build_summary(matches, refund_total):
    unmatched_ids = sorted(set(result['order_id'] for result in matches if result['status'] == 'unmatched'))
    total_orders = len(matches)
    matched_count = sum(1 for result in matches if result['status'] == 'matched')
    net_total = sum(result['amount'] for result in matches if result['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

