"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    s = s.strip()
    if s.count('.') > 1 or (s.startswith('-') and s[1:].count('.') > 1):
        return None
    try:
        amount = Decimal(s)
    except InvalidOperation:
        return None

    if amount < 0:
        if amount > -Decimal('1000000.00'):
            return int(amount * 100)
        else:
            return None
    else:
        if amount > Decimal('1000000.00'):
            return None
        return int(amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP) * 100)


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields
    record_type = record_type.upper().strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()

    if not record_id or not order_id or not order_id.startswith('ORD-'):
        return None

    try:
        amount = parse_amount(amount_str.strip())
    except (ValueError, InvalidOperation):
        return None

    if currency.strip() != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'status': 'unmatched',
                'amount': 0,
                'timestamp': record['timestamp']
            }
        elif record['type'] == 'PAYMENT' and record['amount'] < 0:
            payments.append(record)

    for order_id, order in orders.items():
        for payment in payments:
            if payment['order_id'] == order_id:
                if order['timestamp'] <= payment['timestamp'] < order['timestamp'] + timedelta(hours=72):
                    if order['status'] == 'unmatched' or payment['timestamp'] < orders[order_id]['timestamp']:
                        orders[order_id]['status'] = 'matched'
                        orders[order_id]['amount'] += -payment['amount']
                        orders[order_id]['timestamp'] = payment['timestamp']

    return [{'order_id': order_id, 'status': order['status'], 'amount': order['amount']} for order_id, order in orders.items()]


def compute_refunds(records):
    refund_total = 0
    valid_orders = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_orders:
            refund_total += -record['amount']

    return int(refund_total)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] != 'matched'))

    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

