"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = int(Decimal(s) * 100)
        if abs(amount) > 1000000:
            return None
        return amount
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    if record_type.upper() != 'ORDER' and record_type.upper() != 'PAYMENT':
        return None
    amount = parse_amount(amount)
    if amount is None or currency != 'USD':
        return None
    if record_type.upper() == 'ORDER' and amount < 0:
        return None
    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.fromisoformat(order['timestamp'].replace('Z', '+00:00'))
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= datetime.fromisoformat(payment['timestamp'].replace('Z', '+00:00')) < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: (datetime.fromisoformat(p['timestamp'].replace('Z', '+00:00')), payments.index(p)))
            results.append({'order_id': order_id, 'status': 'matched', 'amount': earliest_payment['amount']})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(matched_count - refund_total, 0)
    unmatched_ids = sorted(set(match.get('id') for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

