"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if not isinstance(s, str) or s.count('.') > 1 or 'e' in s.lower():
            return None
        value = Decimal(s)
        if value != value.to_integral_value():
            value = value.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)
        cents = int(value * 100)
        if abs(cents) > 1000000:
            return None
        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) < 6:
        return None

    record_type = parts[0].upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parts[3].strip()
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    parsed_amount = parse_amount(amount)
    if record_type == 'ORDER' and parsed_amount is not None and parsed_amount < 0:
        return None
    if record_type == 'PAYMENT' and parsed_amount is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record is not None:
            record_id = record['record_id']
            if record_id not in seen_ids:
                seen_ids.add(record_id)
                records.append(record)

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'amount': record['amount'],
                'timestamp': record['timestamp']
            }

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order = orders[order_id]
                if 0 <= record['amount'] and order['timestamp'] <= record['timestamp'] < order['timestamp'] + timedelta(hours=72):
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    # Remove the order once matched
                    del orders[order_id]
                else:
                    results.append({
                        'order_id': order_id,
                        'status': 'unmatched',
                        'amount': 0
                    })

    for order_id in orders:
        results.append({
            'order_id': order_id,
            'status': 'unmatched',
            'amount': 0
        })

    return results


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

