"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for valid range
        if abs(amount) > 1000000:
            return None

        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to cents as integer
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = parts
    record_type = record_type.strip().upper()
    order_id = order_id.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    if not order_id.startswith('ORD-'):
        return None

    amount = parse_amount(amount_str.strip())
    if amount is None:
        return None

    timestamp = timestamp.strip()
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id,
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = []
    seen_ids = set()

    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            valid_records.append(record)
            seen_ids.add(record['record_id'])

    return valid_records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'timestamp': datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S'),
                'amount': record['amount']
            }
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        order_time = order['timestamp']
        matched_amount = 0

        for payment in payments:
            payment_time = datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S')
            if payment['order_id'] == order_id and order_time <= payment_time < order_time + timedelta(hours=72):
                matched_amount += -payment['amount']  # Payments are negative amounts
                break  # Only take the earliest payment

        results.append({
            'order_id': order_id,
            'status': 'matched' if matched_amount > 0 else 'unmatched',
            'amount': matched_amount if matched_amount > 0 else 0
        })

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            total_refund += -record['amount']  # Add positive value of the refund

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(0, net_total)
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

