"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount_decimal = Decimal(s)
        amount_cents = int(amount_decimal * 100 + 0.5)  # Round half up
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        amount_decimal = Decimal(amount)
        amount_cents = int(amount_decimal * 100 + 0.5)  # Round half up
        if amount_cents < 0 or amount_cents > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type.upper(),
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp_dt
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    for record in records:
        if record['TYPE'] == 'ORDER':
            order_id = record['ORDER_ID']
            order_timestamp = record['TIMESTAMP']
            amount_needed = record['AMOUNT']
            matched = False
            for payment in sorted(
                (r for r in records if r['TYPE'] == 'PAYMENT' and r['ORDER_ID'] == order_id and r['TIMESTAMP'] < order_timestamp + timedelta(hours=72)),
                key=lambda x: (x['TIMESTAMP'], records.index(x))
            ):
                if amount_needed + payment['AMOUNT'] >= 0:
                    amount_needed += payment['AMOUNT']
                    matched = True
                    break
            matches.append({
                'order_id': order_id,
                'status': 'matched' if matched else 'unmatched',
                'amount': 0 if not matched else -amount_needed
            })
    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in order_ids:
            refund_total += -record['AMOUNT']  # Add positive amount

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'refund_total': refund_total,
        'unmatched_ids': unmatched_ids
    }

