"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    s = s.strip()
    if s.count('.') > 1 or 'e' in s.lower() or 'E' in s:
        return None
    try:
        amount = Decimal(s)
    except InvalidOperation:
        return None
    if abs(amount) > 1000000:
        return None
    return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = parts
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    currency = currency.strip()
    if record_type not in {'ORDER', 'PAYMENT'} or not record_id or not order_id.startswith('ORD-') or currency != 'USD' or amount is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    results = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for order_id, order in orders.items():
        matched_payment = None
        for record in records:
            if (record['type'] == 'PAYMENT' and 
                record['amount'] >= 0 and 
                record['order_id'] == order_id and 
                order['timestamp'] <= record['timestamp'] < order['timestamp'] + timedelta(hours=72)):

                if matched_payment is None or record['timestamp'] < matched_payment['timestamp']:
                    matched_payment = record

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            total_refund += -record['amount']
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

