"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid numeric string
        if not isinstance(s, str) or s.count('.') > 1 or 'e' in s.lower():
            return None

        # Convert to Decimal and round
        amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        cents = int(amount * 100)

        # Ensure absolute value does not exceed 1,000,000 cents
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = parse_amount(fields[3])
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if not record_id or not order_id or not amount:
        return None

    if not order_id.startswith('ORD-'):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    seen_ids = set()
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            seen_ids.add(record['RECORD_ID'])
            valid_records.append(record)

    return valid_records


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['ORDER_ID']
        order_time = order['TIMESTAMP']
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order_id and payment['AMOUNT'] < 0:
                if payment['TIMESTAMP'] < order_time and (order_time - payment['TIMESTAMP']) < timedelta(hours=72):
                    if matched_payment is None or payment['TIMESTAMP'] < matched_payment['TIMESTAMP']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': abs(matched_payment['AMOUNT'])
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0:
            if record['ORDER_ID'] in valid_orders:
                refund_total += abs(record['AMOUNT'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(set(match['order_id'] for match in matches))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches) - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

