"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for scientific notation
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal for accurate rounding
        amount = Decimal(s)

        # Validate the amount
        if abs(amount) > 1000000:
            return None

        # Round to two decimal places and convert to integer cents
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, parts)

    # Validate TYPE
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None

    # Validate RECORD_ID and ORDER_ID
    if not record_id or not order_id.startswith('ORD-'):
        return None

    # Validate AMOUNT
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None

    # Validate CURRENCY
    if currency != 'USD':
        return None

    # Validate TIMESTAMP format
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type.upper(),
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            seen_ids.add(record['RECORD_ID'])
            records.append(record)

    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] >= 0]

    for order in orders:
        order_timestamp = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        qualifying_payments = [
            payment for payment in payments
            if payment['ORDER_ID'] == order['ORDER_ID'] and
            order_timestamp < datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S') < order_timestamp + timedelta(hours=72)
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: (datetime.strptime(p['TIMESTAMP'], '%Y-%m-%d %H:%M:%S'), payments.index(p)))
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'matched',
                'amount': earliest_payment['AMOUNT']
            })
        else:
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in order_ids and record['AMOUNT'] < 0:
            refund_total += abs(record['AMOUNT'])

    return refund_total


def build_summary(matches, refund_total):
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    total_orders = len(matches)
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

