"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    raise NotImplementedError


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip():
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount_decimal = Decimal(amount)
        if amount_decimal < 0 or abs(amount_decimal) > 1000000:
            return None
        amount_decimal = amount_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id.strip(),
        'amount': amount_decimal,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'status': 'unmatched',
                'amount': Decimal('0'),
                'timestamp': record['timestamp']
            }

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] >= 0:
            for order_id, order in orders.items():
                if order['timestamp'] <= record['timestamp'] < order['timestamp'] + timedelta(hours=72):
                    if order['status'] == 'unmatched' or record['timestamp'] < orders[order_id]['timestamp']:
                        orders[order_id]['status'] = 'matched'
                        orders[order_id]['amount'] = record['amount']
                        orders[order_id]['timestamp'] = record['timestamp']

    return [{'order_id': order_id, 'status': order['status'], 'amount': order['amount']} for order_id, order in orders.items()]


def compute_refunds(records):
    refund_total = Decimal('0.00')
    valid_orders = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_orders:
            refund_total += abs(record['amount'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = sum(1 for match in matches if match['status'] == 'matched' or match['status'] == 'unmatched')
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, Decimal('0.00'))
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

