"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s:
        return None
    if s.count('.') > 1 or 'e' in s.lower():
        return None
    try:
        amount_decimal = Decimal(s)
    except (InvalidOperation, ValueError):
        return None
    if abs(amount_decimal) > 1000000:
        return None
    amount_rounded = amount_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return int(amount_rounded * 100)  # Convert to integer cents


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id or not amount or not currency or not timestamp:
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount_decimal = Decimal(amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None

    if abs(amount_decimal) > 1000000:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_decimal,
        'currency': currency,
        'timestamp': timestamp_dt
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    matches = []

    for payment in payments:
        matched = False
        for order_id, order in orders.items():
            if payment['timestamp'] < order['timestamp'] + timedelta(hours=72) and payment['timestamp'] >= order['timestamp']:
                matches.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': int(payment['amount'] * 100)  # Convert to integer cents
                })
                matched = True
                break

        if not matched:
            matches.append({
                'order_id': payment['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    total_refund = Decimal('0.00')

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])

    return int(total_refund * 100)  # Convert to integer cents


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

