"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100) if amount >= 0 else -int(-amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_str = fields[3].strip()
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if not record_id:
        return None
    if not amount_str.isdigit() and not (amount_str.replace('.', '', 1).isdigit() and amount_str.count('.') <= 1):
        return None
    amount = Decimal(amount_str).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    if abs(amount) > 1000000:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = {}
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['RECORD_ID'] not in records:
            records[record['RECORD_ID']] = record
    return list(records.values())


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    matches = []

    for order in orders:
        order_time = order['TIMESTAMP']
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order['ORDER_ID'] and payment['TIMESTAMP'] < order_time + timedelta(hours=72):
                matched_payment = payment
                break

        if matched_payment:
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'matched',
                'amount': abs(matched_payment['AMOUNT'])
            })
        else:
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in order_ids and record['AMOUNT'] < 0:
            refund_total += -record['AMOUNT']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

