"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid characters and format
        if not isinstance(s, str) or not s.replace('.', '', 1).replace('-', '', 1).isdigit():
            return None

        # Reject scientific notation
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal for precise rounding
        amount = Decimal(s)

        # Round to three decimal places
        amount = amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)

        # Convert to cents
        cents = int(amount * 100)

        # Check for absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 6:
        return None

    record_type = parts[0].upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if amount is None:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    if not isinstance(text, str) or not text.strip():
        return []

    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record['timestamp']

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] >= 0:
            order_time = orders.get(record['order_id'])
            if order_time and order_time <= record['timestamp'] < order_time + timedelta(hours=72):
                results.append({
                    'order_id': record['order_id'],
                    'status': 'matched',
                    'amount': record['amount']
                })
            else:
                results.append({
                    'order_id': record['order_id'],
                    'status': 'unmatched',
                    'amount': 0
                })

    return results


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += -record['amount']  # Convert to positive

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

