"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for scientific notation
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal and validate
        amount = Decimal(s)

        # Check for absolute value greater than 1,000,000 cents
        if abs(amount) > 1000000:
            return None

        # Round to nearest cent using round-half-up
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = parts

    # Validate TYPE
    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    # Validate RECORD_ID and ORDER_ID
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    # Validate AMOUNT
    amount = parse_amount(amount_str.strip())
    if amount is None:
        return None

    # Validate CURRENCY
    currency = currency.strip()
    if currency != 'USD':
        return None

    # Validate TIMESTAMP
    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    orders = {record['ORDER_ID']: record for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] >= 0:
            order_id = record['ORDER_ID']
            if order_id in orders:
                order_timestamp = orders[order_id]['TIMESTAMP']
                payment_timestamp = record['TIMESTAMP']
                if order_timestamp < payment_timestamp < order_timestamp + timedelta(hours=72):
                    matches.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['AMOUNT']
                    })
                    continue
        matches.append({
            'order_id': record['ORDER_ID'],
            'status': 'unmatched',
            'amount': 0
        })

    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in order_ids and record['AMOUNT'] < 0:
            refund_total += abs(record['AMOUNT'])

    return refund_total


def build_summary(matches, refund_total):
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': len(matches),
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

