"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s.replace(',', ''))
        if amount < -1000000 or amount > 1000000:
            return None
        return int(amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[5].strip()
    timestamp = parts[4].strip()

    if not record_id or not order_id.startswith('ORD-') or currency != 'USD' or amount is None:
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0]

    for order in orders:
        order_timestamp = datetime.fromisoformat(order['timestamp'].replace('Z', '+00:00'))
        eligible_payments = [
            payment for payment in payments
            if payment['order_id'] == order['order_id'] and 
            order_timestamp < datetime.fromisoformat(payment['timestamp'].replace('Z', '+00:00')) < order_timestamp + timedelta(hours=72)
        ]

        if eligible_payments:
            selected_payment = min(eligible_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': selected_payment['amount']
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            if record['order_id'] in order_ids:
                refund_total += -record['amount']  # Add positive magnitude of the negative payment

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

