"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()

    if record_type not in {'ORDER', 'PAYMENT'}:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    if currency.strip() != 'USD':
        return None

    parsed_amount = parse_amount(amount.strip())
    if parsed_amount is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': parsed_amount,
        'CURRENCY': currency.strip(),
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            record_id = record['RECORD_ID']
            if record_id not in seen_ids:
                seen_ids.add(record_id)
                records.append(record)

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders[record['ORDER_ID']] = record
        elif record['TYPE'] == 'PAYMENT':
            payments.append(record)

    results = []
    for order_id, order in orders.items():
        matched_payment = None
        order_timestamp = order['TIMESTAMP']

        for payment in payments:
            if payment['ORDER_ID'] == order_id and payment['TIMESTAMP'] < order_timestamp + timedelta(hours=72):
                if matched_payment is None or payment['TIMESTAMP'] < matched_payment['TIMESTAMP']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -matched_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}
    refund_sum = sum(-record['AMOUNT'] for record in records if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_orders and record['AMOUNT'] < 0)
    return refund_sum


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

