"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = int(Decimal(s) * 100)
        if abs(amount) > 1000000:
            return None
        return amount
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type != 'ORDER' or not record_id or not order_id.startswith('ORD-') or amount is None or currency != 'USD':
        return None

    return {
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    results = []
    current_time = datetime.utcnow()

    for record in records:
        order_id = record['ORDER_ID']
        amount = record['AMOUNT']
        timestamp = datetime.fromisoformat(record['TIMESTAMP'].replace('Z', '+00:00'))
        status = 'unmatched'

        if amount >= 0:  # Non-refund payments
            end_time = timestamp + timedelta(hours=72)
            if timestamp <= current_time < end_time:  # Changed to strictly less than 72 hours
                status = 'matched'

        results.append({
            'order_id': order_id,
            'status': status,
            'amount': 0 if status == 'unmatched' else amount
        })

    return results


def compute_refunds(records):
    return sum(-record['AMOUNT'] for record in records if record['AMOUNT'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['AMOUNT'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['ORDER_ID'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

