"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid format
        if s.count('.') > 1:
            return None

        # Convert to Decimal for rounding
        amount = Decimal(s)

        # Apply round-half-up for third fractional digits
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to cents
        cents = int(amount * 100)

        # Check constraints
        if cents < 0 or abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-') or not order_id[4:].strip():
        return None
    try:
        amount = int(amount)
        if amount < 0 or amount > 1000000:
            return None
    except ValueError:
        return None
    if currency != 'USD':
        return None
    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record is not None:
            if record['record_id'] not in seen_ids:
                seen_ids.add(record['record_id'])
                records.append(record)

    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    for order in orders:
        matched_amount = 0
        order_timestamp = order['timestamp']
        for payment in payments:
            if payment['order_id'] == order['order_id'] and order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72):
                matched_amount += payment['amount']

        if matched_amount > 0:
            matches.append({'order_id': order['order_id'], 'status': 'matched', 'amount': matched_amount})
        else:
            matches.append({'order_id': order['order_id'], 'status': 'unmatched', 'amount': 0})

    return matches


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += -record['amount']  # Convert to positive

    return refund_total


def build_summary(matches, refund_total):
    total_orders = sum(1 for match in matches if match['status'] == 'unmatched' or match['status'] == 'matched')
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

