"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal for accurate rounding
        amount = Decimal(s)

        # Round to three decimal places and convert to cents
        amount_cents = int((amount * 100).to_integral_value(rounding=ROUND_HALF_UP))

        # Check for absolute value limit
        if abs(amount_cents) > 1000000:
            return None

        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    currency = currency.strip()
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    amount_cents = parse_amount(amount)
    if record_type == 'ORDER' and amount_cents is not None and amount_cents < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    results = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT':
            order = orders.get(record['order_id'])
            if order:
                order_time = order['timestamp']
                payment_time = record['timestamp']
                if payment_time >= order_time and payment_time < order_time + timedelta(hours=72):
                    results.append({
                        'order_id': record['order_id'],
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue
        results.append({
            'order_id': record['order_id'],
            'status': 'unmatched',
            'amount': 0
        })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    total_orders = len(matches)

    total_matched_amount = sum(match['amount'] for match in matches if match['status'] == 'matched')
    net_total = max(total_matched_amount - refund_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

