"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100)  # Convert to cents
    except (ValueError, InvalidOperation):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type != 'ORDER' or not record_id or not order_id.startswith('ORD-') or amount is None or currency != 'USD':
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    raise NotImplementedError


def match_payments(records):
    matched = []
    for record in records:
        if record['type'] == 'ORDER':
            order_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            payment_window_start = order_time
            payment_window_end = order_time + timedelta(hours=72)
            matched_payment = None

            for payment in records:
                if payment['type'] == 'PAYMENT' and payment['order_id'] == record['order_id']:
                    payment_time = datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S')
                    if payment_window_start <= payment_time < payment_window_end:
                        matched_payment = payment
                        break

            matched.append({
                'order_id': record['order_id'],
                'amount': matched_payment['amount'] if matched_payment else 0,
                'status': 'matched' if matched_payment else 'unmatched'
            })
    return matched


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': max(net_total, 0),
        'unmatched_ids': unmatched_ids
    }

