"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        parts = s.split('.')
        if len(parts) > 2 or (len(parts) == 2 and len(parts[1]) > 3):
            return None
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount)
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in {'ORDER', 'PAYMENT'}:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id[4:]:
        return None
    if currency != 'USD':
        return None
    if record_type == 'ORDER' and amount is not None and amount < 0:
        return None
    if record_type == 'PAYMENT' and amount is None:
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S') if ' ' in order['timestamp'] else datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M')
        eligible_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and
            order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') < order_timestamp + timedelta(hours=72)
        ]

        if eligible_payments:
            earliest_payment = min(eligible_payments, key=lambda p: (datetime.strptime(p['timestamp'], '%Y-%m-%d %H:%M:%S'), payments.index(p)))
            results.append({'order_id': order_id, 'status': 'matched', 'amount': earliest_payment['amount']})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += abs(record['amount'])
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches) - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

