"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if not isinstance(s, str):
            return None
        # Check for scientific notation
        if 'e' in s or 'E' in s:
            return None
        # Convert to Decimal
        amount = Decimal(s)
        # Check for valid range
        if abs(amount) > 1000000:
            return None
        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        # Convert to cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = parts

    # Validate TYPE
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None

    # Validate ORDER_ID
    if not order_id.strip().startswith('ORD-'):
        return None

    # Validate AMOUNT and CURRENCY
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate TIMESTAMP
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    # If it's an ORDER with a negative amount, it's invalid
    if record_type.upper() == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id.strip(),
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = {}
    result = []

    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in valid_records:
            valid_records[record['record_id']] = record
            result.append(record)

    return result


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            order_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            orders[record['order_id']] = (order_time, record['amount'])
        elif record['type'] == 'PAYMENT':
            payment_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            payments.append((payment_time, record))

    results = []

    for order_id, (order_time, order_amount) in orders.items():
        matched_payment = None

        for payment_time, payment in payments:
            if payment['order_id'] == order_id and order_time <= payment_time < order_time + timedelta(hours=72):
                if matched_payment is None or payment_time < matched_payment[0]:
                    matched_payment = (payment_time, payment)

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': order_amount
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            total_refund += abs(record['amount'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

