"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        if s.count('.') > 1 or 'e' in s.lower() or 'E' in s:
            return None
        amount = Decimal(s)
        if amount != amount.to_integral_value(rounding=ROUND_HALF_UP):
            amount = amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)
        amount_cents = int(amount * 100)
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip():
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount = Decimal(amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        if abs(amount) > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = {}
    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in valid_records:
            valid_records[record['record_id']] = record
    return list(valid_records.values())


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    matches = []
    for payment in payments:
        matched_order = None
        for order_id, order in orders.items():
            if (order['timestamp'] <= payment['timestamp'] < order['timestamp'] + timedelta(hours=72)):
                if matched_order is None or order['timestamp'] < matched_order['timestamp']:
                    matched_order = order

        if matched_order:
            matches.append({
                'order_id': matched_order['order_id'],
                'status': 'matched',
                'amount': payment['amount']
            })
        else:
            matches.append({
                'order_id': payment['order_id'],
                'status': 'unmatched',
                'amount': Decimal('0.00')
            })

    return matches


def compute_refunds(records):
    total_refund = Decimal('0.00')
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, Decimal('0.00'))
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

