"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount_decimal = Decimal(s)
        if amount_decimal != amount_decimal.to_integral_value(rounding=ROUND_HALF_UP):
            return None
        amount_cents = int(amount_decimal * 100)
        if abs(amount_cents) > 1000000:
            return None
        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id or not order_id.startswith('ORD-'):
        return None
    try:
        amount_decimal = Decimal(amount)
        if amount_decimal != amount_decimal.to_integral_value(rounding=ROUND_HALF_UP):
            return None
        amount_cents = int(amount_decimal * 100)
        if abs(amount_cents) > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None
    if currency != 'USD':
        return None
    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp_dt
    }


def load_records(text):
    records = {}
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None and record['RECORD_ID'] not in records:
            records[record['RECORD_ID']] = record
    return list(records.values())


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    matches = []

    for order in orders:
        order_timestamp = order['TIMESTAMP']
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order['ORDER_ID'] and payment['TIMESTAMP'] < order_timestamp + timedelta(hours=72):
                matched_payment = payment
                break

        if matched_payment:
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'matched',
                'amount': -matched_payment['AMOUNT']
            })
        else:
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    refund_total = 0
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_orders and record['AMOUNT'] < 0:
            refund_total += -record['AMOUNT']  # Add positive value of negative amount

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

