"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    s = s.strip()
    if not s:
        return None

    try:
        # Check for optional minus sign and split on decimal point
        if s[0] == '-':
            negative = True
            s = s[1:]
        else:
            negative = False

        if s.count('.') > 1:
            return None

        # Convert to Decimal for accurate rounding
        amount_decimal = Decimal(s)
        if amount_decimal < 0:
            return None

        # Round to cents
        amount_cents = int((amount_decimal * 100).to_integral_value(rounding=ROUND_HALF_UP))

        if abs(amount_cents) > 1000000:
            return None

        return -amount_cents if negative else amount_cents

    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        amount_decimal = Decimal(amount)
        amount_cents = int(amount_decimal * 100 + 0.5)
        if amount_cents < 0 or amount_cents > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp_dt
    }


def load_records(text):
    records = {}
    valid_records = []

    for line in text.strip().splitlines():
        parsed_record = parse_record(line)
        if parsed_record and parsed_record['RECORD_ID'] not in records:
            records[parsed_record['RECORD_ID']] = parsed_record
            valid_records.append(parsed_record)

    return valid_records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = order['TIMESTAMP']
        qualifying_payments = [
            payment for payment in payments
            if payment['ORDER_ID'] == order_id and
            0 < (payment['TIMESTAMP'] - order_timestamp).total_seconds() < 72 * 3600
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: p['TIMESTAMP'])
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -earliest_payment['AMOUNT']
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in order_ids:
            refund_total += -record['AMOUNT']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'refund_total': refund_total,
