"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for invalid formats
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for absolute value exceeding $10,000.00
        if abs(amount) > 10000:
            return None

        # Round to nearest cent
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 5:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount_str = parts[3].strip()
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-') or len(order_id) <= 4:
        return None
    if record_type == 'ORDER' and parse_amount(amount_str) is None:
        return None
    if currency != 'USD':
        return None
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    amount = parse_amount(amount_str)
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = {}
    for line in lines:
        record = parse_record(line)
        if record is not None and record['record_id'] not in valid_records:
            valid_records[record['record_id']] = record
    return list(valid_records.values())


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []
    for order_id, order in orders.items():
        matched_amount = 0
        for payment in payments:
            if payment['order_id'] == order_id and payment['timestamp'] < order['timestamp'] + timedelta(hours=72):
                matched_amount += -payment['amount']

        if matched_amount > order['amount']:
            matched_amount = order['amount']

        if matched_amount > 0:
            results.append({'order_id': order_id, 'status': 'matched', 'amount': matched_amount})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['order_id'] in order_ids and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

