"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    s = s.strip()
    if not s.replace('.', '', 1).replace('-', '', 1).isdigit():
        return None

    amount = Decimal(s)
    if abs(amount) > 1000000:
        return None

    return int(round(amount * 100, 0))


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_str = fields[3].strip()
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if not record_id or not order_id.startswith('ORD-'):
        return None

    if not amount_str.replace('.', '', 1).replace('-', '', 1).isdigit():
        return None

    amount = round(Decimal(amount_str) * 100)
    if abs(amount) > 1000000:
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': int(amount),
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    order_dict = {}

    for record in records:
        if record['TYPE'] == 'ORDER':
            order_dict[record['ORDER_ID']] = {
                'amount': record['AMOUNT'],
                'timestamp': record['TIMESTAMP'],
                'matched_payment': None
            }

    for record in records:
        if record['TYPE'] == 'PAYMENT':
            for order_id, order in order_dict.items():
                if order['matched_payment'] is None and order['timestamp'] < record['TIMESTAMP'] < order['timestamp'] + timedelta(hours=72):
                    order['matched_payment'] = record['AMOUNT']
                    matches.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': abs(record['AMOUNT'])
                    })
                    break

    for order_id, order in order_dict.items():
        if order['matched_payment'] is None:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in order_ids:
            total_refund += abs(record['AMOUNT'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

