"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for valid range
        if abs(amount) > 1000000:
            return None

        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to cents as integer
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = parts
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    if not order_id.startswith('ORD-'):
        return None

    amount = parse_amount(amount)
    if amount is None:
        return None

    # Validate timestamp format
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = {}
    result = []

    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in valid_records:
            valid_records[record['record_id']] = record
            result.append(record)

    return result


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            order_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            orders[record['order_id']] = (record['amount'], order_time)
        elif record['type'] == 'PAYMENT':
            payment_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
            payments.append((record['order_id'], -record['amount'], payment_time))

    results = []

    for order_id, (order_amount, order_time) in orders.items():
        matched_amount = 0
        for payment_order_id, payment_amount, payment_time in payments:
            if payment_order_id == order_id and order_time <= payment_time < order_time + timedelta(hours=72):
                if payment_amount > matched_amount:
                    matched_amount = payment_amount

        results.append({
            'order_id': order_id,
            'status': 'matched' if matched_amount > 0 else 'unmatched',
            'amount': matched_amount
        })

    return results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and any(r['order_id'] == record['order_id'] for r in records))


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

