"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        value = Decimal(s)
        if value.as_tuple().exponent < -2 or abs(value) > 1000000:
            return None
        return int(value.to_integral_value(rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-') or not record_id or not order_id:
        return None
    if currency != 'USD':
        return None
    if parse_amount(amount) is None:
        return None
    if record_type.upper() == 'ORDER' and parse_amount(amount) < 0:
        return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': parse_amount(amount),
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record

    for record in records:
        if record['type'] == 'PAYMENT':
            order = orders.get(record['order_id'])
            if order:
                order_time = datetime.fromisoformat(order['timestamp'].replace('Z', '+00:00'))
                payment_time = datetime.fromisoformat(record['timestamp'].replace('Z', '+00:00'))
                if order_time <= payment_time < order_time + timedelta(hours=72):
                    results.append({
                        'order_id': record['order_id'],
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue

        results.append({
            'order_id': record['order_id'],
            'status': 'unmatched',
            'amount': 0
        })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] != 'matched'})
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    total_orders = len(matches)
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

