"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if '.' in s:
            amount = int(Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
        else:
            amount = int(s)
        if abs(amount) > 1000000:
            return None
        return amount
    except (ValueError, TypeError, InvalidOperation):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type != 'ORDER' or not record_id or not order_id.startswith('ORD-') or amount is None or currency != 'USD':
        return None

    return {
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and not any(r['record_id'] == record['record_id'] for r in records):
            records.append(record)
    return records


def match_payments(records):
    results = []
    orders = [record for record in records if 'ORDER_ID' in record]

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = datetime.fromisoformat(order['TIMESTAMP'].replace('Z', '+00:00'))
        matched = {
            'ORDER_ID': order_id,
            'status': 'unmatched',
            'amount': 0
        }

        # Check for payments within strictly less than 72 hours
        for record in records:
            if 'AMOUNT' in record and 'TIMESTAMP' in record:
                payment_timestamp = datetime.fromisoformat(record['TIMESTAMP'].replace('Z', '+00:00'))
                if payment_timestamp >= order_timestamp and payment_timestamp < order_timestamp + timedelta(hours=72):
                    matched['status'] = 'matched'
                    matched['amount'] = record['AMOUNT']
                    break

        results.append(matched)

    return results


def compute_refunds(records):
    return sum(record['AMOUNT'] for record in records if 'AMOUNT' in record and record['AMOUNT'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, matched_count - refund_total)
    unmatched_ids = sorted(set(match['ORDER_ID'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

