"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    s = s.strip()
    if not s:
        return None
    negative = s.startswith('-')
    if negative:
        s = s[1:]

    if s.count('.') > 1 or (s.count('.') == 1 and len(s.split('.')[-1]) > 3):
        return None

    try:
        amount_decimal = Decimal(s).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)
        if abs(amount_decimal) > 1000000:
            return None
        amount_cents = int(amount_decimal * 100)
        return -amount_cents if negative else amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if not amount.replace('.', '', 1).isdigit() or (record_type == 'ORDER' and float(amount) < 0):
        return None
    if currency != 'USD':
        return None

    try:
        amount_decimal = Decimal(amount).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)
        if abs(amount_decimal) > 1000000:
            return None
        amount_cents = int(amount_decimal * 100)
    except (InvalidOperation, ValueError):
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp_dt
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        parsed_record = parse_record(line)
        if parsed_record and parsed_record['record_id'] not in seen_ids:
            records.append(parsed_record)
            seen_ids.add(parsed_record['record_id'])
    return records


def match_payments(records):
    matches = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}
    payments = sorted(
        [record for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0],
        key=lambda x: (x['timestamp'], x['record_id'])
    )

    for order_id, order in orders.items():
        matched_amount = 0
        for payment in payments:
            if payment['order_id'] == order_id and order['timestamp'] <= payment['timestamp'] < order['timestamp'] + timedelta(hours=72):
                matched_amount += -payment['amount']
                break  # Only the earliest payment qualifies

        status = 'matched' if matched_amount > 0 else 'unmatched'
        matches.append({
            'order_id': order_id,
            'status': status,
            'amount': matched_amount
        })

    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']  # Add positive value of refund

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)  # Ensure net_total is not negative

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

