"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    s = s.strip()
    if s.count('.') > 1 or ('-' in s and s[0] != '-') or (s[0] == '-' and len(s) == 1):
        return None
    if s.count('-') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    if s.startswith('-'):
        sign = -1
        s = s[1:]
    else:
        sign = 1
    if s.count('.') == 1:
        integer_part, fractional_part = s.split('.')
        if len(fractional_part) > 3:
            return None
        fractional_part = fractional_part.ljust(3, '0')[:3]
    else:
        integer_part, fractional_part = s, '0'
    if len(integer_part) > 0 and integer_part.isdigit() and fractional_part.isdigit():
        amount = int(integer_part) * 100 + int(fractional_part)
        if abs(amount) > 1000000:
            return None
        return sign * amount
    return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    record_type = record_type.upper()

    if not record_id or not order_id.startswith('ORD-'):
        return None

    if currency != 'USD':
        return None

    amount = parse_amount(amount)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    results = []
    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids)
    return refund_total if refund_total > 0 else 0


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

