"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 10000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 5:
        return None

    record_type, record_id, amount_str, currency, timestamp_str = parts
    record_type = record_type.strip().upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.startswith('ORD-') or len(record_id) <= 4:
        return None
    if record_type == 'ORDER' and parse_amount(amount_str) is None:
        return None
    if currency.strip() != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    amount = parse_amount(amount_str)

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': record_id,
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = {}
    result = []

    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in valid_records:
            valid_records[record['record_id']] = record
            result.append(record)

    return result


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []
    for payment in payments:
        order = orders.get(payment['order_id'])
        if order:
            time_difference = payment['timestamp'] - order['timestamp']
            if timedelta(0) < time_difference < timedelta(hours=72):
                results.append({
                    'order_id': order['order_id'],
                    'status': 'matched',
                    'amount': -payment['amount']
                })
            else:
                results.append({
                    'order_id': order['order_id'],
                    'status': 'unmatched',
                    'amount': 0
                })
        else:
            results.append({
                'order_id': payment['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['order_id'] in order_ids and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

