"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Reject scientific notation
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal for rounding
        amount = Decimal(s)

        # Validate the amount
        if abs(amount) > 1000000:
            return None

        # Round to nearest cent
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-') or not order_id[4:].strip():
        return None
    if currency != 'USD':
        return None

    try:
        amount = int(amount)
        if abs(amount) > 1000000 or (record_type == 'ORDER' and amount < 0):
            return None
    except ValueError:
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    results = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order = orders[order_id]
                payment_time_window = order['timestamp'] + timedelta(hours=72)
                if order['timestamp'] <= record['timestamp'] < payment_time_window and record['amount'] < 0:
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': -record['amount']
                    })
                    continue
        results.append({
            'order_id': record['order_id'],
            'status': 'unmatched',
            'amount': 0
        })

    return results


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['order_id'] in order_ids and record['amount'] < 0:
            total_refund += -record['amount']  # Add positive value of refund

    return total_refund


def build_summary(matches, refund_total):
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': len(matches),
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

