"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_str = fields[3].strip()
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if not record_id:
        return None

    try:
        amount = round(Decimal(amount_str) * 100).to_integral_value(rounding=ROUND_HALF_UP)
        if amount < 0 or amount > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': int(amount),
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        parsed_record = parse_record(line)
        if parsed_record and parsed_record['RECORD_ID'] not in seen_ids:
            seen_ids.add(parsed_record['RECORD_ID'])
            records.append(parsed_record)

    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = sorted([record for record in records if record['TYPE'] == 'PAYMENT'], key=lambda x: x['TIMESTAMP'])

    for order in orders:
        order_timestamp = order['TIMESTAMP']
        order_id = order['ORDER_ID']
        matched_amount = 0

        for payment in payments:
            payment_timestamp = payment['TIMESTAMP']
            if payment['ORDER_ID'] == order_id and payment_timestamp < order_timestamp + timedelta(hours=72):
                matched_amount += abs(payment['AMOUNT'])
                payments.remove(payment)  # Remove to prevent double matching
                break

        if matched_amount > 0:
            matches.append({'order_id': order_id, 'status': 'matched', 'amount': matched_amount})
        else:
            matches.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in order_ids:
            refund_total += abs(record['AMOUNT'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'refund_total': refund_total,
        'unmatched_ids': unmatched_ids
    }

