"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid amount format
        if not s or not s.replace('.', '', 1).isdigit() or s.count('.') > 1:
            return None

        # Convert to Decimal and round if necessary
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None

        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 6:
        return None

    record_type = parts[0].upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parts[3].strip()
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id[4:].strip():
        return None
    if not amount.replace('.', '', 1).isdigit() or amount.count('.') > 1:
        return None
    if currency != 'USD':
        return None

    try:
        dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    if record_type == 'ORDER' and Decimal(amount) < 0:
        return None
    if record_type == 'PAYMENT' and Decimal(amount) > 0:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': dt
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = order['TIMESTAMP']
        end_time = order_timestamp + timedelta(hours=72)

        qualifying_payments = [
            payment for payment in payments
            if payment['ORDER_ID'] == order_id and order_timestamp <= payment['TIMESTAMP'] < end_time
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: (p['TIMESTAMP'], payments.index(p)))
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': parse_amount(earliest_payment['AMOUNT'])
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    unique_matches = {match['order_id']: match for match in matches}
    return list(unique_matches.values())


def compute_refunds(records):
    refund_total = 0
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in valid_orders:
            refund_total += abs(parse_amount(record['AMOUNT']))

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

