"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not all(field.strip() for field in [record_id, order_id]):
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        amount = Decimal(amount).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None

    if amount.as_tuple().exponent < -3:
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': str(amount),
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = {}
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in records:
            records[record['RECORD_ID']] = record
            valid_records.append(record)

    return valid_records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = sorted([record for record in records if record['TYPE'] == 'PAYMENT'], key=lambda x: x['TIMESTAMP'])

    for order in orders:
        order_time = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        matched = False
        for payment in payments:
            payment_time = datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
            if payment['ORDER_ID'] == order['ORDER_ID'] and payment_time < order_time + timedelta(hours=72):
                matches.append({'order_id': order['ORDER_ID'], 'status': 'matched', 'amount': abs(float(payment['AMOUNT']))})
                matched = True
                break
        if not matched:
            matches.append({'order_id': order['ORDER_ID'], 'status': 'unmatched', 'amount': 0})

    return matches


def compute_refunds(records):
    refund_total = Decimal('0.00')
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and Decimal(record['AMOUNT']) < 0:
            if record['ORDER_ID'] in order_ids:
                refund_total += abs(Decimal(record['AMOUNT']))

    return float(refund_total)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': float(refund_total),
        'net_total': float(net_total),
        'unmatched_ids': unmatched_ids
    }

