"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -2 or abs(amount) > 1000000:
            return None
        return int(amount.to_integral_value(rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id[4:]:
        return None
    if currency != 'USD':
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None or (record_type.upper() == 'ORDER' and parsed_amount < 0):
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    results = []

    for order in orders:
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
        eligible_payments = [
            payment for payment in payments
            if order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S') < order_timestamp + timedelta(hours=72)
        ]

        if eligible_payments:
            earliest_payment = min(eligible_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)
    return refund_total if refund_total < 0 else 0


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

