"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for invalid characters and scientific notation
        if any(char not in '0123456789.-' for char in s) or 'e' in s or 'E' in s:
            return None

        # Convert to Decimal and round
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None

        # Round to nearest cent
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3].strip()
    currency = fields[4].strip()
    timestamp = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-') or not order_id:
        return None

    amount_cents = parse_amount(amount)
    if record_type == 'ORDER' and amount_cents is not None and amount_cents < 0:
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    seen_ids = set()
    records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids and record['CURRENCY'] == 'USD':
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0]

    for order in orders:
        order_timestamp = order['TIMESTAMP']
        matched_amount = 0
        matched = False

        for payment in payments:
            payment_timestamp = payment['TIMESTAMP']
            if order['ORDER_ID'] == payment['ORDER_ID'] and (payment_timestamp - order_timestamp <= timedelta(hours=72)):
                matched_amount += abs(payment['AMOUNT'])
                matched = True

        matches.append({
            'order_id': order['ORDER_ID'],
            'status': 'matched' if matched else 'unmatched',
            'amount': matched_amount if matched else 0
        })

    return matches


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in order_ids:
            refund_total += abs(record['AMOUNT'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(match['amount'] for match in matches if match['status'] == 'matched')
    net_total = max(matched_count - refund_total, 0)
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

