"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount_decimal = Decimal(s)
        if amount_decimal != amount_decimal.to_integral_value(rounding=ROUND_HALF_UP):
            amount_decimal = amount_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        amount_cents = int(amount_decimal * 100)

        if abs(amount_cents) > 1000000:
            return None

        return amount_cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)

    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    if not record_id or not order_id.startswith('ORD-') or not order_id:
        return None

    try:
        amount_decimal = Decimal(amount)
        if amount_decimal < -1000000 or amount_decimal > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount_decimal,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp_dt
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            seen_ids.add(record['RECORD_ID'])
            records.append(record)

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders[record['ORDER_ID']] = record
        elif record['TYPE'] == 'PAYMENT' and record['AMOUNT'] >= 0:
            payments.append(record)

    matches = []

    for order_id, order in orders.items():
        order_timestamp = order['TIMESTAMP']
        match_found = False
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order_id:
                if order_timestamp < payment['TIMESTAMP'] < order_timestamp + timedelta(hours=72):
                    if not match_found or payment['TIMESTAMP'] < matched_payment['TIMESTAMP']:
                        matched_payment = payment
                        match_found = True

        if match_found:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['AMOUNT']
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': Decimal('0.00')
            })

    return matches


def compute_refunds(records):
    total_refund = Decimal('0.00')

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0:
            total_refund += abs(record['AMOUNT'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

