"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount_decimal = Decimal(s)
        if abs(amount_decimal) > 1000000:
            return None
        return int(amount_decimal.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if not amount.replace('.', '', 1).isdigit() or (record_type == 'ORDER' and float(amount) < 0):
        return None
    if currency != 'USD':
        return None

    try:
        amount_decimal = Decimal(amount)
        if abs(amount_decimal) > 1000000:
            return None
        amount_cents = int(amount_decimal.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp_dt
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'timestamp': record['timestamp'],
                'amount': record['amount'],
                'matched_payment': None
            }

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            for order_id, order in orders.items():
                if order['matched_payment'] is None and order['timestamp'] <= record['timestamp'] < order['timestamp'] + timedelta(hours=72):
                    if order['matched_payment'] is None or record['timestamp'] < orders[order['matched_payment']]['timestamp']:
                        order['matched_payment'] = record['record_id']

    for order_id, order in orders.items():
        if order['matched_payment'] is not None:
            matched_payment = next(r for r in records if r['record_id'] == order['matched_payment'])
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            total_refund += -record['amount']

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

