"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        # Check for valid input format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        # Convert to Decimal
        amount = Decimal(s)
        # Check for valid range
        if abs(amount) > 1000000:
            return None
        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        # Return in cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    if currency.strip() != 'USD':
        return None

    amount = parse_amount(amount_str.strip())
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp_str.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id.strip(),
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    orders = [r for r in records if r['type'] == 'ORDER']
    payments = [r for r in records if r['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        valid_payments = [
            p for p in payments
            if p['timestamp'] >= order_timestamp and p['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if valid_payments:
            earliest_payment = min(valid_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            order_id = record['order_id']
            if any(r['order_id'] == order_id and r['type'] == 'ORDER' for r in records):
                refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

