"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        # Check for valid format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None
        # Convert to Decimal for rounding
        amount = Decimal(s)
        # Check for valid range
        if abs(amount) > 1000000:
            return None
        # Round and convert to cents
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount.strip())
    currency = currency.strip()
    timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        matched_payment = None
        order_timestamp = order['timestamp']
        order_id = order['order_id']

        for payment in payments:
            if (payment['order_id'] == order_id and 
                order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72) and 
                (matched_payment is None or payment['timestamp'] < matched_payment['timestamp'])):
                matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    valid_orders = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_orders)
    return refund_total if refund_total > 0 else 0


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

