"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s or s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    try:
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None
    if amount == amount.to_integral_value():
        cents = int(amount)
    else:
        cents = int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    if abs(cents) > 1000000:
        return None
    return cents


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None
    record_type, record_id, order_id, amount_str, currency, timestamp_str = parts
    record_type = record_type.upper().strip()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None
    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None
    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_str, fmt)
            break
        except ValueError:
            continue
    if timestamp is None:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = []
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders.append(record)
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order in orders:
        matched_payment = None
        order_timestamp = order['timestamp']
        for payment in payments:
            if payment['order_id'] == order['order_id'] and payment['amount'] >= 0:
                if order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72):
                    if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

