"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type != 'ORDER' or not record_id or not order_id.startswith('ORD-') or amount is None or currency != 'USD':
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if 'ORDER_ID' in record]
    payments = [record for record in records if 'AMOUNT' in record and record['AMOUNT'] >= 0]
    results = []

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        end_time = order_timestamp + timedelta(hours=72)

        qualifying_payments = [
            payment for payment in payments
            if order_timestamp <= datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S') < end_time
        ]

        if qualifying_payments:
            earliest_payment = min(qualifying_payments, key=lambda p: (p['TIMESTAMP'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    return sum(record['AMOUNT'] for record in records if 'AMOUNT' in record and record['AMOUNT'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['AMOUNT'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['ORDER_ID'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

