"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount_decimal = Decimal(s).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None

    if abs(amount_decimal) > 1000000:
        return None

    return int(amount_decimal * 100) if amount_decimal >= 0 else int(amount_decimal * 100)


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if not amount.replace('.', '', 1).isdigit() or (record_type == 'ORDER' and float(amount) < 0):
        return None
    if currency != 'USD':
        return None

    try:
        dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    amount_decimal = Decimal(amount).quantize(Decimal('0.001'), rounding=ROUND_HALF_UP)
    if abs(amount_decimal) > 1000000:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': int(amount_decimal * 100),
        'currency': currency,
        'timestamp': dt
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'timestamp': record['timestamp'],
                'amount': record['amount'],
                'matched': False
            }
        elif record['type'] == 'PAYMENT' and record['amount'] < 0:
            payments.append(record)

    results = []
    for order_id, order in orders.items():
        matched_payment = None
        for payment in payments:
            if payment['order_id'] == order_id:
                if order['timestamp'] <= payment['timestamp'] < order['timestamp'] + timedelta(hours=72):
                    if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                        matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -matched_payment['amount']
            })
            payments.remove(matched_payment)
            orders[order_id]['matched'] = True
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            total_refund += -record['amount']  # Convert to positive

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    net_total = sum(match['amount'] for match in matches) - refund_total
    net_total = max(net_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

