"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input
        if not isinstance(s, str) or not s.strip():
            return None
        # Convert to Decimal
        amount = Decimal(s)
        # Check for valid range
        if abs(amount) > 1000000:
            return None
        # Round to cents
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        # Return in cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    timestamp = None
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S"):
        try:
            timestamp = datetime.strptime(timestamp_str, fmt)
            break
        except ValueError:
            continue
    if timestamp is None:
        return None

    amount = parse_amount(amount_str)
    if record_type == 'ORDER' and amount is not None and amount < 0:
        return None
    if record_type == 'PAYMENT' and amount is not None and amount >= 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = {}
    result = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in records:
            records[record['record_id']] = record
            result.append(record)
    return result


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record

    for order_id, order in orders.items():
        matched_payment = None
        for record in records:
            if (record['type'] == 'PAYMENT' and 
                record['amount'] >= 0 and 
                record['order_id'] == order_id and 
                order['timestamp'] <= record['timestamp'] < order['timestamp'] + timedelta(hours=72)):

                if matched_payment is None or record['timestamp'] < matched_payment['timestamp']:
                    matched_payment = record

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

