"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not all(field.strip() for field in [record_id, order_id]):
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount = str(round(Decimal(amount), 2))
    except (InvalidOperation, ValueError):
        return None

    if currency != 'USD':
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = {}
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in records:
            records[record['RECORD_ID']] = record
            valid_records.append(record)

    return valid_records


def match_payments(records):
    matches = []
    for record in records:
        if record['TYPE'] == 'ORDER':
            order_timestamp = datetime.strptime(record['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
            matched_payment = None
            for payment in records:
                if payment['TYPE'] == 'PAYMENT' and payment['ORDER_ID'] == record['ORDER_ID']:
                    payment_timestamp = datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
                    if payment_timestamp < order_timestamp and (order_timestamp - payment_timestamp) < timedelta(hours=72):
                        if matched_payment is None or payment_timestamp < matched_payment['TIMESTAMP']:
                            matched_payment = payment

            if matched_payment:
                matches.append({
                    'order_id': record['ORDER_ID'],
                    'status': 'matched',
                    'amount': parse_amount(matched_payment['AMOUNT'])
                })
            else:
                matches.append({
                    'order_id': record['ORDER_ID'],
                    'status': 'unmatched',
                    'amount': 0
                })
    return matches


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'].startswith('-'):
            if record['ORDER_ID'] in valid_order_ids:
                refund_total += abs(parse_amount(record['AMOUNT']))

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

