"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Remove commas and convert to Decimal
        amount = Decimal(s.replace(',', ''))
        # Check for valid range
        if abs(amount) > 1000000:
            return None
        # Round to two decimal places and convert to integer cents
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    try:
        parsed_timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': parsed_amount,
        'CURRENCY': currency,
        'TIMESTAMP': parsed_timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            record_id = record['RECORD_ID']
            if record_id not in seen_record_ids:
                seen_record_ids.add(record_id)
                records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = order['TIMESTAMP']
        matched_payments = [
            payment for payment in payments 
            if payment['ORDER_ID'] == order_id and 
            payment['TIMESTAMP'] > order_timestamp and 
            payment['TIMESTAMP'] <= order_timestamp + timedelta(hours=72)
        ]

        if matched_payments:
            earliest_payment = min(matched_payments, key=lambda p: p['TIMESTAMP'])
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -earliest_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}
    refund_sum = sum(-record['AMOUNT'] for record in records if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_orders and record['AMOUNT'] < 0)
    return refund_sum


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

