"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s:
        return None
    if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    if s.startswith('-'):
        s = s[1:]
    if s.count('.') == 1:
        integer_part, fractional_part = s.split('.')
        if len(fractional_part) > 3:
            return None
        amount = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    else:
        amount = Decimal(s)

    if abs(amount) > 1000000:
        return None

    return int(amount * 100) if amount >= 0 else int(amount * 100)


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip():
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount = Decimal(amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        if abs(amount) > 1000000:
            return None
    except (InvalidOperation, ValueError):
        return None

    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    matches = []

    for payment in payments:
        matched = False
        for order_id, order in orders.items():
            if payment['timestamp'] < order['timestamp'] + timedelta(hours=72) and payment['timestamp'] >= order['timestamp']:
                matches.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': payment['amount']
                })
                matched = True
                break

        if not matched:
            matches.append({
                'order_id': payment['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    total_refund = Decimal('0.00')
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            total_refund += abs(record['amount'])
    return int(total_refund * 100)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(0, net_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

