"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    try:
        amount = Decimal(s)
        if amount.as_tuple().exponent < -2 or abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None
    amount = parse_amount(amount)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None
    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['type'] == 'ORDER':
            if not any(r['record_id'] == record['record_id'] for r in records):
                records.append(record)
        elif record and record['type'] == 'PAYMENT':
            records.append(record)
    return records


def match_payments(records):
    orders = [r for r in records if r['type'] == 'ORDER']
    payments = [r for r in records if r['type'] == 'PAYMENT']
    results = []

    for order in orders:
        order_timestamp = order['timestamp']
        eligible_payments = [
            p for p in payments
            if p['amount'] >= 0 and 
            order_timestamp <= p['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if eligible_payments:
            chosen_payment = min(eligible_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': chosen_payment['amount']
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    return sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and any(r['order_id'] == record['order_id'] for r in records if r['type'] == 'ORDER'))


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

