"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal for accurate rounding
        amount = Decimal(s)

        # Round to nearest cent using round-half-up
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to cents
        cents = int(amount * 100)

        # Check for absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or not currency == 'USD':
        return None

    amount = parse_amount(amount_str)
    if amount is None and record_type == 'PAYMENT':
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            seen_record_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    results = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for order_id, order in orders.items():
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
        matched_payment = None

        for record in records:
            if record['type'] == 'PAYMENT' and record['order_id'] == order_id:
                payment_timestamp = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
                if payment_timestamp >= order_timestamp and payment_timestamp < order_timestamp + timedelta(hours=72):
                    if matched_payment is None or payment_timestamp < matched_payment['timestamp']:
                        matched_payment = record

        if matched_payment:
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids)
    return refund_total


def build_summary(matches, refund_total):
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    total_orders = len(matches)

    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

