"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Reject scientific notation and invalid formats
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal for precision
        amount = Decimal(s)

        # Handle negative amounts as-is
        if abs(amount) > 1000000:
            return None

        # Round to two decimal places
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = map(str.strip, fields)

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if currency != 'USD':
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount = parse_amount(amount_str)
        if amount is None:
            return None
    except Exception:
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    if amount < 0 and record_type == 'ORDER':
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] >= 0]

    for order in orders:
        order_time = order['TIMESTAMP']
        eligible_payments = [
            payment for payment in payments 
            if order_time < payment['TIMESTAMP'] < order_time + timedelta(hours=72)
        ]

        if eligible_payments:
            earliest_payment = min(eligible_payments, key=lambda p: p['TIMESTAMP'])
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'matched',
                'amount': earliest_payment['AMOUNT']
            })
            payments.remove(earliest_payment)  # Remove matched payment from future consideration
        else:
            matches.append({
                'order_id': order['ORDER_ID'],
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in valid_order_ids:
            total_refund += -record['AMOUNT']  # Add positive value of refund

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)  # Ensure net_total is not negative
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

