"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not s or not isinstance(s, str):
        return None
    s = s.strip()
    if not s or s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    try:
        amount = Decimal(s.replace(',', ''))
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if record_type not in ('ORDER', 'PAYMENT'):
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None
    if amount is None:
        return None
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = {}
    valid_records = []
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None and record['record_id'] not in records:
            records[record['record_id']] = record
            valid_records.append(record)
    return valid_records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]

    for order in orders:
        order_timestamp = order['timestamp']
        eligible_payments = [
            payment for payment in payments
            if payment['order_id'] == order['order_id'] and 
            order_timestamp < payment['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if eligible_payments:
            selected_payment = min(eligible_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': selected_payment['amount']
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            if record['order_id'] in order_ids:
                refund_total += -record['amount']  # Add positive magnitude of negative amount

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches) - refund_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

