"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
            return None

        # Convert to Decimal and round
        amount = Decimal(s)
        if amount == amount.to_integral_value():
            cents = int(amount * 100)
        else:
            cents = int(amount.quantize(Decimal('0.001'), rounding=ROUND_HALF_UP) * 100)

        # Check for absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip() or not amount.strip() or not currency.strip():
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        parsed_amount = parse_amount(amount)
        if parsed_amount is None:
            return None

        # Validate timestamp format
        try:
            if len(timestamp) == 16:
                timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
            else:
                timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
        except ValueError:
            return None

        return {
            'type': record_type.upper(),
            'record_id': record_id.strip(),
            'order_id': order_id.strip(),
            'amount': parsed_amount,
            'currency': currency.strip(),
            'timestamp': timestamp
        }
    except Exception:
        return None


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    results = []
    orders = {record['order_id']: record for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order = orders[order_id]
                if record['amount'] >= 0 and order['timestamp'] <= record['timestamp'] < order['timestamp'] + timedelta(hours=72):
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    refund_total = sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids)
    return max(refund_total, 0)


def build_summary(matches, refund_total):
    unmatched_ids = sorted(set(result['order_id'] for result in matches if result['status'] == 'unmatched'))
    matched_count = sum(1 for result in matches if result['status'] == 'matched')
    total_orders = len(matches)
    net_total = max(sum(result['amount'] for result in matches if result['status'] == 'matched') - refund_total, 0)

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

