"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) < 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = parts

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    try:
        amount = Decimal(amount_str).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None
    if amount < 0 or amount > 1000000:
        return None
    if currency != 'USD':
        return None
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for order_id, order in orders.items():
        matched_payments = [p for p in payments if p['timestamp'] < order['timestamp'] + timedelta(hours=72)]
        if matched_payments:
            earliest_payment = min(matched_payments, key=lambda p: (p['timestamp'], p['record_id']))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': Decimal('0.00')
            })

    return results


def compute_refunds(records):
    total_refund = Decimal('0.00')

    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            total_refund += abs(record['amount'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, Decimal('0.00'))
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

