"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not s or not isinstance(s, str):
        return None
    try:
        amount = Decimal(s.replace(',', ''))
        if amount < -1000000 or amount > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None
    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT'] or not record_id or not order_id.startswith('ORD-') or amount is None or currency != 'USD':
        return None

    try:
        dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': dt
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = sorted(
        [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0],
        key=lambda x: (x['timestamp'], records.index(x))
    )

    for order in orders:
        matched_payment = None
        order_time = order['timestamp']
        for payment in payments:
            if payment['order_id'] == order['order_id']:
                if payment['timestamp'] < order_time + timedelta(hours=72):
                    matched_payment = payment
                    break

        if matched_payment:
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

