"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 10000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 5:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    amount = parse_amount(parts[2].strip())
    currency = parts[3].strip()
    timestamp_str = parts[4].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.startswith('ORD-') or not record_id[4:].strip():
        return None
    if amount is None and record_type == 'ORDER':
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': record_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = {}
    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in valid_records:
            valid_records[record['record_id']] = record
    return list(valid_records.values())


def match_payments(records):
    matches = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']

    for order in orders:
        order_timestamp = order['timestamp']
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order['order_id'] and 
            order_timestamp < payment['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: p['timestamp'])
            matches.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': -earliest_payment['amount']
            })
        else:
            matches.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['order_id'] in order_ids)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

