"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = amount.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if not (record_id and order_id) or currency != 'USD':
        return None

    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = {
                'timestamp': record['timestamp'],
                'record_id': record['record_id'],
                'amount': record['amount']
            }
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for payment in payments:
        order_id = payment['order_id']
        if order_id in orders:
            order = orders[order_id]
            order_time = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S') if ':' in order['timestamp'] else datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M')
            if order_time <= datetime.now() <= order_time + timedelta(hours=72):
                results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': payment['amount']
                })
                continue

        results.append({
            'order_id': order_id,
            'status': 'unmatched',
            'amount': 0
        })

    return results


def compute_refunds(records):
    return sum(record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0) * -1


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['record_id'] for match in matches if match['status'] != 'matched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

