"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    s = s.strip()
    if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    if s.count('-') > 1 or (s.count('-') == 1 and s[0] != '-'):
        return None
    if s.count('.') == 1 and len(s.split('.')[1]) > 2:
        return None
    try:
        amount = Decimal(s)
    except InvalidOperation:
        return None
    if abs(amount) > 1000000:
        return None
    return int(amount.to_integral_value(rounding=ROUND_HALF_UP) * 100) if amount >= 0 else int(amount.to_integral_value(rounding=ROUND_HALF_UP) * 100)


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.strip().upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None
    currency = currency.strip()
    if currency != 'USD':
        return None
    amount_cents = parse_amount(amount)
    if amount_cents is None or (record_type == 'ORDER' and amount_cents < 0):
        return None
    if not (isinstance(timestamp, str) and (len(timestamp) == 16 or len(timestamp) == 19)):
        return None
    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M') if len(timestamp) == 16 else datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None
    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S' if len(order['timestamp']) == 19 else '%Y-%m-%d %H:%M')
        matching_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and
            order_timestamp <= datetime.strptime(payment['timestamp'], '%Y-%m-%d %H:%M:%S' if len(payment['timestamp']) == 19 else '%Y-%m-%d %H:%M') < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({'order_id': order_id, 'status': 'matched', 'amount': earliest_payment['amount']})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    refund_total = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            refund_total += -record['amount']
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

