"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    s = s.strip()
    if s.count('.') > 1 or 'e' in s.lower() or any(c not in '-0123456789.' for c in s):
        return None
    try:
        d = Decimal(s)
        if abs(d) > 1000000:
            return None
        return int(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except InvalidOperation:
        return None


def parse_record(line):
    if not isinstance(line, str) or not line.strip():
        return None
    parts = line.split('|')
    if len(parts) != 6:
        return None
    type_, record_id, order_id, amount, currency, timestamp = map(str.strip, parts)
    if type_.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None
    try:
        amount = parse_amount(amount)
        if amount is None or amount < 0:
            return None
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except (ValueError, TypeError):
        return None
    return {
        'type': type_.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0]
    results = []

    for order in orders:
        matched_payment = None
        for payment in payments:
            if (payment['order_id'] == order['order_id'] and
                order['timestamp'] <= payment['timestamp'] < order['timestamp'] + timedelta(hours=72)):
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment
        if matched_payment:
            results.append({
                'order_id': order['order_id'],
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            results.append({
                'order_id': order['order_id'],
                'status': 'unmatched',
                'amount': 0
            })
    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    if net_total < 0:
        net_total = 0
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

