"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount_decimal = Decimal(s).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None

    if abs(amount_decimal) > 1000000:
        return None

    return int(amount_decimal * 100)  # Convert to cents


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not all(field.strip() for field in [record_id, order_id]):
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency.strip() != 'USD':
        return None

    try:
        amount_decimal = Decimal(amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None
    if amount_decimal.as_tuple().exponent < -3:
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': str(amount_decimal),
        'CURRENCY': currency.strip(),
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = {}
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in records:
            records[record['RECORD_ID']] = record
            valid_records.append(record)

    return valid_records


def match_payments(records):
    matches = []
    for record in records:
        if record['TYPE'] == 'ORDER':
            order_timestamp = datetime.strptime(record['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
            order_id = record['ORDER_ID']
            matched_amount = Decimal('0.00')
            matched = False

            for payment in sorted(
                (r for r in records if r['TYPE'] == 'PAYMENT' and r['ORDER_ID'] == order_id),
                key=lambda x: (datetime.strptime(x['TIMESTAMP'], '%Y-%m-%d %H:%M:%S'), records.index(x))
            ):
                payment_timestamp = datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
                if payment_timestamp < order_timestamp + timedelta(hours=72):
                    matched_amount += abs(Decimal(payment['AMOUNT']))
                    matched = True

            matches.append({
                'order_id': order_id,
                'status': 'matched' if matched else 'unmatched',
                'amount': float(matched_amount) if matched else 0
            })

    return matches


def compute_refunds(records):
    total_refund = Decimal('0.00')

    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and Decimal(record['AMOUNT']) < 0:
            if record['ORDER_ID'] in order_ids:
                total_refund += abs(Decimal(record['AMOUNT']))

    return float(total_refund)  # Return as float for consistency with other monetary values


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

