"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s) or s.count('-') > 1:
            return None
        if s.startswith('-'):
            if s[1:].count('.') > 1 or not any(c.isdigit() for c in s[1:]):
                return None
        else:
            if s.count('.') > 1 or not any(c.isdigit() for c in s):
                return None

        # Convert to Decimal for rounding
        amount = Decimal(s)

        # Round using round-half-up
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        cents = int(amount * 100)

        # Check for absolute value limit
        if abs(cents) > 1000000:
            return None

        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = fields

    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    amount = parse_amount(amount_str)

    if not record_id or not order_id.startswith('ORD-') or not amount or currency != 'USD':
        return None

    timestamp_format = '%Y-%m-%d %H:%M:%S' if ':' in timestamp else '%Y-%m-%d %H:%M'
    try:
        datetime.strptime(timestamp, timestamp_format)
    except ValueError:
        return None

    if record_type == 'ORDER' and amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_record_ids:
            records.append(record)
            seen_record_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] >= 0:
            order = orders.get(record['order_id'])
            if order:
                order_time = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S' if ':' in order['timestamp'] else '%Y-%m-%d %H:%M')
                payment_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S' if ':' in record['timestamp'] else '%Y-%m-%d %H:%M')
                if order_time <= payment_time < order_time + timedelta(hours=72):
                    results.append({
                        'order_id': record['order_id'],
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue
        results.append({
            'order_id': record['order_id'],
            'status': 'unmatched',
            'amount': 0
        })

    return results


def compute_refunds(records):
    refund_total = 0

    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

