"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if amount < 0 or amount > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount_str = fields[3].strip()
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0) or amount > 1000000:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = {}
    result = []

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in records:
            records[record['record_id']] = record
            result.append(record)

    return result


def match_payments(records):
    matches = []
    for record in records:
        if record['type'] == 'ORDER':
            order_id = record['order_id']
            order_timestamp = record['timestamp']
            matched_payment = None

            for payment in records:
                if (payment['type'] == 'PAYMENT' and 
                    payment['order_id'] == order_id and 
                    payment['amount'] >= 0 and 
                    payment['timestamp'] > order_timestamp and 
                    payment['timestamp'] <= order_timestamp + timedelta(hours=72)):

                    if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                        matched_payment = payment

            if matched_payment:
                matches.append({'order_id': order_id, 'status': 'matched', 'amount': matched_payment['amount']})
            else:
                matches.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return matches


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            total_refund += -record['amount']

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches) - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

