"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 6:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parts[3].strip()
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if not (record_type in ['ORDER', 'PAYMENT']):
        return None
    if not order_id.startswith('ORD-'):
        return None
    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': parsed_amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = sorted(
        [record for record in records if record['type'] == 'PAYMENT'],
        key=lambda x: (x['timestamp'], records.index(x))
    )

    matched_orders = set()

    for order in orders:
        order_time = order['timestamp']
        order_id = order['order_id']
        earliest_payment = None

        for payment in payments:
            if payment['order_id'] == order_id and payment['timestamp'] < order_time + timedelta(hours=72):
                if earliest_payment is None or payment['timestamp'] < earliest_payment['timestamp']:
                    earliest_payment = payment

        if earliest_payment and order_id not in matched_orders:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
            matched_orders.add(order_id)
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    refund_total = sum(
        record['amount'] for record in records 
        if record['type'] == 'PAYMENT' and 
        any(order['order_id'] == record['order_id'] for order in records if order['type'] == 'ORDER')
    )
    return abs(refund_total)  # Return as positive integer number of cents


def build_summary(matches, refund_total):
    unique_orders = {match['order_id'] for match in matches}
    total_orders = len(unique_orders)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

