"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not s.replace('.', '', 1).replace('-', '', 1).isdigit():
        return None
    amount = Decimal(s)
    if abs(amount) > 1000000:
        return None
    return int(amount.quantize(Decimal('0.00'), rounding=ROUND_HALF_UP) * 100)


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    if not amount.replace('.', '', 1).replace('-', '', 1).isdigit() or abs(float(amount)) > 1000000:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    amount_cents = int(Decimal(amount).quantize(Decimal('0.00'), rounding=ROUND_HALF_UP) * 100)

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    for record in records:
        if record['TYPE'] == 'ORDER':
            order_id = record['ORDER_ID']
            order_timestamp = record['TIMESTAMP']
            matched_amount = 0
            matched_status = 'unmatched'

            for payment in records:
                if payment['TYPE'] == 'PAYMENT' and payment['ORDER_ID'] == order_id:
                    payment_timestamp = payment['TIMESTAMP']
                    if 0 < (payment_timestamp - order_timestamp).total_seconds() < 259200:  # 72 hours
                        if matched_status == 'unmatched' or payment_timestamp < matched_timestamp:
                            matched_amount = abs(payment['AMOUNT'])
                            matched_status = 'matched'
                            matched_timestamp = payment_timestamp

            matches.append({
                'order_id': order_id,
                'status': matched_status,
                'amount': matched_amount
            })
    return matches


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in order_ids:
            total_refund += abs(record['AMOUNT'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted({match['order_id'] for match in matches if match['status'] == 'unmatched'})

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

