"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        amount = Decimal(s)
        if amount < -1000000 or amount > 1000000:
            return None
        return int(amount.to_integral_value(rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields

    record_type = record_type.upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = record_id.strip()
    order_id = order_id.strip()
    if not order_id.startswith('ORD-') or not order_id:
        return None

    amount = parse_amount(amount)
    if record_type == 'ORDER' and amount is not None and amount < 0:
        return None

    if currency != 'USD':
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    records = {}
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in records:
            records[record['RECORD_ID']] = record
            if record['CURRENCY'] == 'USD':
                valid_records.append(record)

    return valid_records


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] >= 0]
    results = []

    for order in orders:
        order_time = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        matched_payment = None

        for payment in payments:
            payment_time = datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
            if payment['ORDER_ID'] == order['ORDER_ID'] and 0 <= (payment_time - order_time).total_seconds() <= 72 * 3600:
                if matched_payment is None or payment_time < matched_payment['TIMESTAMP']:
                    matched_payment = payment

        if matched_payment:
            results.append({
                'order_id': order['ORDER_ID'],
                'status': 'matched',
                'amount': matched_payment['AMOUNT']
            })
        else:
            results.append({
                'order_id': order['ORDER_ID'],
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in order_ids:
            refund_total += abs(record['AMOUNT'])

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)

    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

