"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    # Implementation for parsing amount
    try:
        amount = Decimal(s)
        if amount.is_nan() or amount.is_infinite():
            return None
        if amount < 0:
            return None
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].upper()
    if record_type not in ['ORDER', 'PAYMENT']:
        return None

    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = parse_amount(fields[3])
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if not record_id or not order_id or not amount or currency != 'USD':
        return None

    if not order_id.startswith('ORD-'):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    seen_ids = set()
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            seen_ids.add(record['RECORD_ID'])
            valid_records.append(record)

    return valid_records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = sorted([record for record in records if record['TYPE'] == 'PAYMENT'], key=lambda x: x['TIMESTAMP'])

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = order['TIMESTAMP']
        matched_payment = None

        for payment in payments:
            if payment['ORDER_ID'] == order_id and payment['TIMESTAMP'] < order_timestamp and (order_timestamp - payment['TIMESTAMP']) < timedelta(hours=72):
                matched_payment = payment
                break

        if matched_payment:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': abs(matched_payment['AMOUNT'])
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    total_refunds = 0
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in valid_orders:
            total_refunds += abs(record['AMOUNT'])

    return total_refunds


def build_summary(matches, refund_total):
    total_orders = len(set(match['order_id'] for match in matches))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

