"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not s.replace('.', '', 1).replace('-', '', 1).isdigit():
        return None
    amount = Decimal(s)
    if abs(amount) > 1000000:
        return None
    return int(round(amount * 100, 0))


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    if not amount.replace('.', '', 1).replace('-', '', 1).isdigit() or abs(round(Decimal(amount) * 100)) > 1000000:
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    amount_cents = int(round(Decimal(amount) * 100, 0))

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = order['TIMESTAMP']
        matched_amount = 0
        matched = False

        for payment in payments:
            if payment['ORDER_ID'] == order_id and payment['TIMESTAMP'] > order_timestamp and payment['TIMESTAMP'] <= order_timestamp + timedelta(hours=72):
                matched_amount += -payment['AMOUNT']
                matched = True

        matches.append({
            'order_id': order_id,
            'status': 'matched' if matched else 'unmatched',
            'amount': matched_amount if matched else 0
        })

    return matches


def compute_refunds(records):
    total_refund = 0
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_orders:
            total_refund += -record['AMOUNT']  # Add as positive value

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches) - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

