"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input format
        if s.count('.') > 1 or any(c not in '0123456789.-' for c in s) or s.count('-') > 1:
            return None
        if s.startswith('-'):
            negative = True
            s = s[1:]
        else:
            negative = False

        # Split into whole and fractional parts
        if '.' in s:
            whole, frac = s.split('.')
            if len(frac) > 3:
                return None
            frac = frac.ljust(3, '0')  # Pad to 3 digits
        else:
            whole = s
            frac = '00'

        if not whole.isdigit() or (whole == '' and frac == '00'):
            return None

        # Convert to integer cents
        amount = int(whole) * 100 + int(frac[:2])
        if negative:
            amount = -amount

        # Check absolute value limit
        if abs(amount) > 1000000:
            return None

        return amount
    except (ValueError, InvalidOperation):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp = fields
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()
    timestamp = timestamp.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id[4:]:
        return None
    if currency != 'USD':
        return None
    if record_type == 'ORDER' and parse_amount(amount_str) is not None and parse_amount(amount_str) < 0:
        return None
    if record_type == 'PAYMENT' and parse_amount(amount_str) is None:
        return None

    amount = parse_amount(amount_str)
    if amount is None:
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record

    for record in records:
        if record['type'] == 'PAYMENT':
            order = orders.get(record['order_id'])
            if order:
                order_time = datetime.strptime(order['timestamp'], '%Y-%m-%d %H:%M:%S')
                payment_time = datetime.strptime(record['timestamp'], '%Y-%m-%d %H:%M:%S')
                if record['amount'] >= 0 and order_time <= payment_time < order_time + timedelta(hours=72):
                    results.append({
                        'order_id': record['order_id'],
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue
            results.append({
                'order_id': record['order_id'],
                'status': 'unmatched',
                'amount': 0
            })

    for order_id in orders:
        if order_id not in [result['order_id'] for result in results]:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in order_ids:
            refund_total += -record['amount']  # Add the magnitude of the negative amount

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

