  "rules": [
    {
      "id": "P1-L1",
      "quote": "Set the shared data and function contracts before implementing behavior."
    },
    {
      "id": "P1-L2",
      "quote": "- Implement `parse_amount(s)`, `parse_record(line)`, `load_records(text)`, `compute_refunds(records)`, `match_payments(records)`, and `build_summary(matches, refund_total)`."
    },
    {
      "id": "P1-L3",
      "quote": "- Store every amount as integer cents and process only `USD` records."
    },
    {
      "id": "P2-L1",
      "quote": "Implement `parse_amount(s)` as the complete amount validator and converter."
    },
    {
      "id": "P2-L2",
      "quote": "- Accept digits with at most one decimal point and an optional leading minus sign;"
    },
    {
      "id": "P2-L3",
      "quote": "scientific notation and all other syntax are invalid."
    },
    {
      "id": "P2-L4",
      "quote": "- Accept at most three fractional digits;"
    },
    {
      "id": "P2-L5",
      "quote": "convert to cents and round a third fractional digit using **round-half-up**."
    },
    {
      "id": "P2-L6",
      "quote": "- Apply rounding to the magnitude, then preserve the original sign, so negative values remain negative."
    },
    {
      "id": "P2-L7",
      "quote": "- Apply the absolute-value limit after conversion: `abs(amount) ≤ 1,000,000` cents."
    },
    {
      "id": "P2-L8",
      "quote": "- Return the converted integer cents for valid input."
    },
    {
      "id": "P2-L9",
      "quote": "- Return `None` for empty, malformed, over-limit, or otherwise invalid input."
    },
    {
      "id": "P2-L10",
      "quote": "- Do not raise or print for invalid input."
    }
  ],
  "checks": [
    {
      "assertion": "assert parse_amount('100.00') == 10000",
      "result": "OBSERVED_PASS",
      "ttl": 1
    },
    {
      "assertion": "assert parse_record('ORD-1234,2023-10-01 12:00:00,USD,100.00') == {'ORDER_ID': 'ORD-1234', 'TIMESTAMP': datetime(2023, 10, 1, 12, 0), 'CURRENCY': 'USD', 'AMOUNT': 10000}",
      "result": "OBSERVED_PASS",
      "ttl": 1
    }
  ],
  "status": {},
  "todo": []
}

