"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for invalid formats
        if 'e' in s or 'E' in s:
            return None

        # Convert to Decimal
        amount = Decimal(s)

        # Check for absolute value exceeding $10,000.00
        if abs(amount) > 10000:
            return None

        # Round to nearest cent using round-half-up
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) < 6:
        return None

    record_type = parts[0].strip().upper()
    record_id = parts[1].strip()
    order_id = parts[2].strip()
    amount = parse_amount(parts[3].strip())
    currency = parts[4].strip()
    timestamp_str = parts[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not order_id.startswith('ORD-') or not order_id[4:].strip():
        return None
    if amount is None and record_type == 'ORDER':
        return None
    if currency != 'USD':
        return None
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    seen_ids = set()
    valid_records = []

    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            valid_records.append(record)

    return valid_records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in orders:
                order = orders[order_id]
                time_difference = record['timestamp'] - order['timestamp']
                if 0 < time_difference < timedelta(hours=72):
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': -record['amount']
                    })
                    continue

            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    order_ids = {record['order_id'] for record in records if record['type'] == 'ORDER'}
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['order_id'] in order_ids and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

