"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str) or not s.strip():
        return None
    s = s.strip()
    if s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    if s.count('-') > 1 or (s.count('-') == 1 and s[0] != '-'):
        return None
    if len(s.split('.')[-1]) > 3:
        return None
    try:
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None
    if abs(amount) > 1000000:
        return None
    return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None
    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = parse_amount(fields[3].strip())
    currency = fields[4].strip()
    timestamp_str = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    if amount is None or abs(amount) > 1000000:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)
    return records


def match_payments(records):
    results = []
    orders = [record for record in records if record['type'] == 'ORDER']
    payments = [record for record in records if record['type'] == 'PAYMENT']

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        valid_payments = [
            payment for payment in payments
            if payment['order_id'] == order_id and 
            order_timestamp <= payment['timestamp'] < order_timestamp + timedelta(hours=72) and 
            payment['amount'] >= 0
        ]

        if valid_payments:
            earliest_payment = min(valid_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0
    valid_orders = {record['order_id'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_orders:
            refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    total_orders = len(matches)

    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    if net_total < 0:
        net_total = 0

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

