"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    s = s.strip()
    if not s or s.count('.') > 1 or any(c not in '0123456789.-' for c in s):
        return None
    if s.count('.') == 1:
        whole, frac = s.split('.')
        if len(frac) > 3:
            return None
        frac = frac.ljust(3, '0')[:3]  # Pad or truncate to 3 digits
    else:
        whole, frac = s, '000'

    if whole.startswith('-'):
        sign = -1
        whole = whole[1:]
    else:
        sign = 1

    if not whole.isdigit() or (whole == '' and sign == -1):
        return None

    amount = int(whole) * 100 + int(frac)
    if sign == -1:
        amount = -amount

    if abs(amount) > 1000000:
        return None

    return amount


def parse_record(line):
    parts = line.strip().split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = parts
    record_type = record_type.upper().strip()
    record_id = record_id.strip()
    order_id = order_id.strip()
    currency = currency.strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-') or not order_id[4:]:
        return None
    if currency != 'USD':
        return None

    amount = parse_amount(amount_str)
    if amount is None or (record_type == 'ORDER' and amount < 0):
        return None

    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            seen_ids.add(record['record_id'])
            records.append(record)

    return records


def match_payments(records):
    orders = [r for r in records if r['type'] == 'ORDER']
    payments = [r for r in records if r['type'] == 'PAYMENT' and r['amount'] >= 0]
    results = []

    for order in orders:
        order_id = order['order_id']
        order_timestamp = order['timestamp']
        valid_payments = [
            p for p in payments
            if order_timestamp <= p['timestamp'] < order_timestamp + timedelta(hours=72)
        ]

        if valid_payments:
            earliest_payment = min(valid_payments, key=lambda p: (p['timestamp'], payments.index(p)))
            results.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': earliest_payment['amount']
            })
        else:
            results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return results


def compute_refunds(records):
    refund_total = 0

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            order_id = record['order_id']
            if any(r['order_id'] == order_id for r in records if r['type'] == 'ORDER'):
                refund_total += -record['amount']

    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

