"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    s = s.strip()
    if 'e' in s or 'E' in s:
        return None
    if s.count('.') > 1:
        return None
    try:
        amount = Decimal(s)
    except (InvalidOperation, ValueError):
        return None
    amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    if abs(amount) > 1000000:
        return None
    return int(amount * 100) if amount >= 0 else int(amount * 100)


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper().strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip():
        return None
    if not order_id.startswith('ORD-'):
        return None

    try:
        amount = Decimal(amount).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return None
    if abs(amount) > 1000000:
        return None

    if currency.strip() != 'USD':
        return None

    try:
        timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp = datetime.strptime(timestamp.strip(), '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'type': record_type,
        'record_id': record_id.strip(),
        'order_id': order_id.strip(),
        'amount': amount,
        'currency': currency.strip(),
        'timestamp': timestamp
    }


def load_records(text):
    lines = text.strip().split('\n')
    valid_records = {}
    result = []

    for line in lines:
        record = parse_record(line)
        if record and record['record_id'] not in valid_records:
            valid_records[record['record_id']] = record
            result.append(record)

    return result


def match_payments(records):
    orders = {}
    payments = []

    for record in records:
        if record['type'] == 'ORDER':
            orders[record['order_id']] = record
        elif record['type'] == 'PAYMENT':
            payments.append(record)

    results = []

    for payment in payments:
        matched = False
        for order_id, order in orders.items():
            if payment['timestamp'] < order['timestamp'] + timedelta(hours=72) and payment['timestamp'] >= order['timestamp']:
                results.append({'order_id': order_id, 'status': 'matched', 'amount': payment['amount']})
                matched = True
                break
        if not matched:
            results.append({'order_id': payment['order_id'], 'status': 'unmatched', 'amount': 0})

    for order_id in orders.keys():
        if not any(result['order_id'] == order_id for result in results):
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    refund_total = 0
    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0:
            refund_total += abs(record['amount'])
    return refund_total


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

