"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Check for valid input
        if s.count('.') > 1 or (s.startswith('-') and len(s) == 1):
            return None

        # Convert to Decimal for precision
        amount = Decimal(s)

        # Check for absolute value limit
        if abs(amount) > 1000000:
            return None

        # Round to nearest cent
        amount = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

        # Convert to integer cents
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount_str, currency, timestamp_str = fields

    # Handle TYPE case-insensitively
    record_type = record_type.upper()

    # Validate RECORD_ID and ORDER_ID
    record_id = record_id.strip()
    order_id = order_id.strip()
    if not record_id or not order_id.startswith('ORD-'):
        return None

    # Parse amount
    amount = parse_amount(amount_str)
    if amount is None:
        return None

    # Validate currency
    if currency != 'USD':
        return None

    # Validate timestamp
    try:
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S') if ':' in timestamp_str else datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    # Validate negative orders
    if amount < 0:
        return None

    return {
        'type': record_type,
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])

    return records


def match_payments(records):
    matches = []
    orders = {}

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id not in orders:
                orders[order_id] = []
            orders[order_id].append(record)

    for order_id, payments in orders.items():
        matched_payment = None
        for payment in payments:
            if payment['amount'] >= 0:
                if matched_payment is None or payment['timestamp'] < matched_payment['timestamp']:
                    matched_payment = payment

        if matched_payment:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': matched_payment['amount']
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['order_id'] for record in records if record['type'] == 'PAYMENT' and record['amount'] >= 0}

    for record in records:
        if record['type'] == 'PAYMENT' and record['amount'] < 0 and record['order_id'] in valid_order_ids:
            total_refund += -record['amount']  # Add positive value of refund

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(0, sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

