"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        # Remove commas and convert to Decimal
        amount = Decimal(s.replace(',', ''))
        # Check for valid range
        if abs(amount) > 1000000:
            return None
        # Round to two decimal places and convert to cents
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.split('|')
    if len(fields) != 6:
        return None

    record_type = fields[0].strip().upper()
    record_id = fields[1].strip()
    order_id = fields[2].strip()
    amount = fields[3].strip()
    currency = fields[4].strip()
    timestamp = fields[5].strip()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id or not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    parsed_amount = parse_amount(amount)
    if parsed_amount is None:
        return None

    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S') if ':' in timestamp else datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': parsed_amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_record_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record is not None:
            if record['RECORD_ID'] not in seen_record_ids:
                seen_record_ids.add(record['RECORD_ID'])
                records.append(record)

    return records


def match_payments(records):
    orders = {}
    results = []

    for record in records:
        if record['TYPE'] == 'ORDER':
            orders[record['ORDER_ID']] = record

    for record in records:
        if record['TYPE'] == 'PAYMENT':
            order_id = record['ORDER_ID']
            if order_id in orders:
                order_timestamp = orders[order_id]['TIMESTAMP']
                payment_timestamp = record['TIMESTAMP']
                if payment_timestamp < order_timestamp + timedelta(hours=72):
                    results.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': -record['AMOUNT']
                    })
                    break
                else:
                    results.append({
                        'order_id': order_id,
                        'status': 'unmatched',
                        'amount': 0
                    })
            else:
                results.append({
                    'order_id': order_id,
                    'status': 'unmatched',
                    'amount': 0
                })

    return results


def compute_refunds(records):
    valid_orders = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}
    refund_sum = sum(-record['AMOUNT'] for record in records if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in valid_orders and record['AMOUNT'] < 0)
    return refund_sum


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = max(sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

