"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    try:
        if 'e' in s or 'E' in s:
            return None
        amount = Decimal(s)
        if abs(amount) > 1000000:
            return None
        return int(amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    parts = line.split('|')
    if len(parts) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, parts)

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.isdigit():
        return None
    if not order_id.startswith('ORD-'):
        return None
    if currency != 'USD':
        return None

    try:
        amount = parse_amount(amount)
        if amount is None:
            return None
    except Exception:
        return None

    try:
        datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id,
        'ORDER_ID': order_id,
        'AMOUNT': amount,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().split('\n'):
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    orders = [record for record in records if record['TYPE'] == 'ORDER']
    payments = [record for record in records if record['TYPE'] == 'PAYMENT']
    results = []

    for order in orders:
        order_id = order['ORDER_ID']
        order_timestamp = datetime.strptime(order['TIMESTAMP'], '%Y-%m-%d %H:%M:%S')
        matching_payments = [
            payment for payment in payments
            if payment['ORDER_ID'] == order_id and payment['AMOUNT'] >= 0 and 
            order_timestamp < datetime.strptime(payment['TIMESTAMP'], '%Y-%m-%d %H:%M:%S') < order_timestamp + timedelta(hours=72)
        ]

        if matching_payments:
            earliest_payment = min(matching_payments, key=lambda p: p['TIMESTAMP'])
            results.append({'order_id': order_id, 'status': 'matched', 'amount': earliest_payment['AMOUNT']})
        else:
            results.append({'order_id': order_id, 'status': 'unmatched', 'amount': 0})

    return results


def compute_refunds(records):
    total_refund = 0
    valid_order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['AMOUNT'] < 0 and record['ORDER_ID'] in valid_order_ids:
            total_refund += -record['AMOUNT']  # Convert to positive for summation

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len([m for m in matches if m['status'] == 'matched' or m['status'] == 'unmatched'])
    matched_count = len([m for m in matches if m['status'] == 'matched'])
    net_total = sum(m['amount'] for m in matches if m['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(m['order_id'] for m in matches if m['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

