"""Blank starter for the detailed reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not s.replace('.', '', 1).replace('-', '', 1).isdigit():
        return None

    amount_decimal = Decimal(s)
    if abs(amount_decimal) > 1000000:
        return None

    return int(amount_decimal.quantize(Decimal('0.00'), rounding=ROUND_HALF_UP) * 100)


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None

    record_type, record_id, order_id, amount, currency, timestamp = fields
    record_type = record_type.upper()

    if record_type not in ['ORDER', 'PAYMENT']:
        return None
    if not record_id.strip() or not order_id.strip().startswith('ORD-'):
        return None
    if not amount.replace('.', '', 1).replace('-', '', 1).isdigit():
        return None

    amount_decimal = Decimal(amount)
    if abs(amount_decimal) > 1000000:
        return None

    amount_cents = int(amount_decimal.quantize(Decimal('0.00'), rounding=ROUND_HALF_UP) * 100)
    if currency != 'USD':
        return None

    try:
        timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    except ValueError:
        try:
            timestamp_dt = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
        except ValueError:
            return None

    return {
        'TYPE': record_type,
        'RECORD_ID': record_id.strip(),
        'ORDER_ID': order_id.strip(),
        'AMOUNT': amount_cents,
        'CURRENCY': currency,
        'TIMESTAMP': timestamp_dt
    }


def load_records(text):
    records = []
    seen_ids = set()

    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['RECORD_ID'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['RECORD_ID'])

    return records


def match_payments(records):
    matches = []
    order_records = {record['ORDER_ID']: record for record in records if record['TYPE'] == 'ORDER'}
    payment_records = [record for record in records if record['TYPE'] == 'PAYMENT']

    for order_id, order in order_records.items():
        earliest_payment = None
        for payment in payment_records:
            if payment['ORDER_ID'] == order_id:
                time_diff = (order['TIMESTAMP'] - payment['TIMESTAMP']).total_seconds()
                if 0 < time_diff < 259200:  # 72 hours in seconds
                    if earliest_payment is None or payment['TIMESTAMP'] < earliest_payment['TIMESTAMP']:
                        earliest_payment = payment

        if earliest_payment:
            matches.append({
                'order_id': order_id,
                'status': 'matched',
                'amount': -earliest_payment['AMOUNT']
            })
        else:
            matches.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matches


def compute_refunds(records):
    total_refund = 0
    order_ids = {record['ORDER_ID'] for record in records if record['TYPE'] == 'ORDER'}

    for record in records:
        if record['TYPE'] == 'PAYMENT' and record['ORDER_ID'] in order_ids:
            total_refund += abs(record['AMOUNT'])

    return total_refund


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(-match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    net_total = max(net_total, 0)
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'refund_total': refund_total,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

